const LOGO_URL = "data:image/png;base64,";
const LOGO_CIRCULO = "data:image/jpeg;base64,";
const today = () => new Date().toISOString().split("T")[0];
const fmtFecha = (f) => { if(!f) return ""; const [y,m,d] = f.split("-"); return `${d}/${m}/${y}`; };
const DIAS_SEMANA = ["domingo","lunes","martes","miércoles","jueves","viernes","sábado"];
// Describe una fecha de vencimiento con el día de la semana y, si ya venció, cuántos
// días hace y que sigue sin hacerse — se usa en pop-ups y listados de Tareas.
const fmtVenceCompleto = (vence) => {
  if (!vence) return "sin fecha";
  const dia = DIAS_SEMANA[new Date(vence+"T00:00:00").getDay()];
  const fechaFmt = fmtFecha(vence);
  const dif = Math.ceil((new Date(vence+"T00:00:00") - new Date(today()+"T00:00:00")) / 86400000);
  if (dif < 0) return `vencida hace ${Math.abs(dif)} día${Math.abs(dif)>1?"s":""} (venció el ${dia} ${fechaFmt}) y sigue sin hacerse`;
  if (dif === 0) return `vence hoy, ${dia} ${fechaFmt}`;
  if (dif === 1) return `vence mañana, ${dia} ${fechaFmt}`;
  return `vence el ${dia} ${fechaFmt}`;
};
// Da estilo uniforme a una frase de pop-up de notificación: solo la primera
// letra en mayúscula, el resto en minúscula, y un punto final si no lo tenía
// ya (admite que termine en "?", "!" o "…" sin añadir punto encima).
const fmtFrase = (s) => {
  if (!s) return s;
  const t = s.trim();
  if (!t) return t;
  const f = t.charAt(0).toUpperCase() + t.slice(1).toLowerCase();
  return /[.!?…]$/.test(f) ? f : f + ".";
};
// Igual que fmtFrase pero sin punto final (para nombres propios cortos, como el
// municipio de un cliente bajo su nombre en los pop-ups de avisos).
const capitalizaNombre = (s) => {
  if (!s) return s;
  const t = s.trim();
  if (!t) return t;
  return t.charAt(0).toUpperCase() + t.slice(1).toLowerCase();
};
// Variante para los pop-ups de Tareas y Avisos: el texto principal (título de
// la tarea o del aviso) va TODO EN MAYÚSCULAS con un punto final; el cliente
// se sigue mostrando aparte, en mayúsculas y en negrita (ver render del pop-up).
const fraseMayus = (s) => {
  if (!s) return s;
  const t = s.trim().toUpperCase();
  return t && !/[.!?…]$/.test(t) ? t + "." : t;
};
// Añade un punto final a una frase si no lo tiene ya, sin tocar mayúsculas ni
// minúsculas (para el texto de "vencida hace.../vence el..." de las tareas,
// que ya viene en minúsculas desde fmtVenceCompleto).
const conPunto = (s) => {
  if (!s) return s;
  const t = s.trim();
  return t && !/[.!?…]$/.test(t) ? t + "." : t;
};
const generarNum = (prefijo, fecha, lista, campoNum) => {
  // Format: P010926-01, AV010926-01, ALB010926-01
  const d = fecha || today();
  const [y,m,day] = d.split("-");
  const base = prefijo + day + m + y.slice(2); // ej: P010926
  const delDia = lista.filter(x => x[campoNum] && x[campoNum].startsWith(base));
  const seq = String(delDia.length + 1).padStart(2, "0");
  return base + "-" + seq;
};
// Keep backward compat alias
const generarNumParte = (fecha, partes) => generarNum("P", fecha, partes, "numeroParte");
// Lista de nombres asignados/tecnicos: soporta el array nuevo (varios) y el string legacy (uno solo)
const listaNombres = (obj, campoArray, campoLegacy) => {
  const arr = obj && obj[campoArray];
  if (Array.isArray(arr) && arr.length) return arr;
  const legacy = obj && obj[campoLegacy];
  return legacy ? [legacy] : [];
};
const fmtNombres = (obj, campoArray, campoLegacy) => listaNombres(obj, campoArray, campoLegacy).join(" y ") || "—";
// Cadena de partes continuados: varios partes del mismo trabajo (visitas distintas), identificados
// por compartir "cadenaBase" (el numeroParte del parte original). Si un parte no tiene cadenaBase
// (datos antiguos o parte suelto) se usa su propio numeroParte como base.
const cadenaBaseDe = p => (p && (p.cadenaBase || p.numeroParte)) || ("id-" + (p && p.id));
const obtenerCadenaPartes = (partes, p) => (partes||[]).filter(x => cadenaBaseDe(x) === cadenaBaseDe(p)).sort((a,b)=>(a.numContinuacion||0)-(b.numContinuacion||0));

const diasDesde = (f) => { const d = Math.floor((new Date() - new Date(f)) / 86400000); return d < 0 ? 0 : d; };
const uid = () => Date.now() + Math.random();
// Quita tildes/diacríticos para que "vias" encuentre "VÍAS", "compresor" encuentre
// "COMPRESÓR", etc. — la búsqueda no debe depender de que el usuario escriba acentos.
const sinAcentos = (s) => String(s||"").normalize("NFD").replace(/[̀-ͯ]/g,"");
// Búsqueda multi-palabra: cada palabra escrita debe aparecer en alguno de los
// campos indicados (en cualquier orden), así "bosch rodamiento" encuentra un
// artículo aunque "bosch" esté en el proveedor y "rodamiento" en el nombre.
const coincideTexto = (item, query, campos) => {
  const palabras = sinAcentos(query).toLowerCase().trim().split(/\s+/).filter(Boolean);
  if (palabras.length === 0) return true;
  const texto = sinAcentos(campos.map(c => String(item?.[c] ?? "")).join(" ")).toLowerCase();
  return palabras.every(p => texto.includes(p));
};
// ─── Secciones de datos (guardado por sección, no como blob único) ───────────
// Cada clave de 'data' listada aquí tiene su propia fila en la BD con su propio
// version counter. Cambiar clientes no entra en conflicto con cambiar avisos.
// Las claves no listadas van a la sección 'config' (usuarios, smtp, passwords…).
const SECCIONES_ACTIVAS = ['clientes','avisos','partes','reparaciones','tareas','ventas','visitas','chat','calendario','inventario'];
const TODAS_SECCIONES = [...SECCIONES_ACTIVAS, 'config'];

// Extrae los datos de una sección desde el objeto data completo.
// Para secciones activas devuelve el array/objeto de esa clave.
// Para 'config' devuelve un objeto con todas las claves que no tienen sección propia.
function extraerSeccion(d, s) {
  if(s === 'config'){
    const c={};
    Object.keys(d).forEach(k=>{ if(!SECCIONES_ACTIVAS.includes(k)) c[k]=d[k]; });
    return c;
  }
  return d[s] ?? (Array.isArray((initialData||{})[s]) ? [] : {});
}

// Aplica los datos de una sección sobre el objeto data completo.
function aplicarSeccion(d, s, sd) {
  if(s === 'config') return {...d, ...sd};
  return {...d, [s]: sd};
}

// ID del cliente interno "Europea de Maquinaria – Maquinaria Nueva" (stock de máquinas nuevas)
const CLIENTE_STOCK_ID = -1;
// Usuarios con acceso a información económica confidencial (precio de compra y precio de venta objetivo).
// Se compara normalizado (sin tildes, minúsculas) para mayor tolerancia.
const _USUARIOS_PRECIO_CONF = ["raul ibars","cristina tarin","geles tarin","manuel tarin"];
const _normNombre = s => (s||"").toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g,"");
const puedeVerPrecioConf = u => u?.rol==="manager"||u?.rol==="admin"||_USUARIOS_PRECIO_CONF.includes(_normNombre(u?.nombre));

// Código interno único de máquina, compartido entre Stock (máquinas en venta) y
// las máquinas de cada cliente — para que nunca se repita un código entre ambos.
const nextCodigoMaquina = (data) => {
  const nums = [];
  (data.clientes||[]).forEach(c=>(c.maquinas||[]).forEach(m=>{ const n=parseInt((m.codigo||"").replace(/^MAQ-?/,""))||0; if(n) nums.push(n); }));
  const max = nums.length ? Math.max(...nums) : 0;
  return "MAQ-"+String(max+1).padStart(4,"0");
};
// Asigna un código a las máquinas de clientes (incluido el cliente interno de stock)
// que aún no lo tengan. Devuelve el mismo objeto si no hay nada que rellenar.
const backfillCodigosMaquina = (d) => {
  const usados = new Set();
  (d.clientes||[]).forEach(c=>(c.maquinas||[]).forEach(m=>{ if(m.codigo) usados.add(m.codigo); }));
  let max = 0;
  usados.forEach(cod=>{ const n=parseInt((cod||"").replace(/^MAQ-?/,""))||0; if(n>max) max=n; });
  let changed = false;
  const sig = () => { max+=1; return "MAQ-"+String(max).padStart(4,"0"); };
  const clientes = (d.clientes||[]).map(c=>{
    const maquinas = (c.maquinas||[]).map(m=>{ if(m.codigo) return m; changed=true; return {...m, codigo:sig()}; });
    return {...c, maquinas};
  });
  return changed ? {...d, clientes} : d;
};
// Migra el array legacy data.stock[] al cliente interno CLIENTE_STOCK_ID (id=-1).
// También garantiza que ese cliente exista en data.clientes[].
// Idempotente: si stock ya está vacío, solo asegura que el cliente -1 esté presente.
const migrateStockToCliente = (d) => {
  let clientes = [...(d.clientes||[])];
  // Asegurar que el cliente interno de stock existe
  if (!clientes.find(c=>c.id===CLIENTE_STOCK_ID)) {
    clientes = [{
      id: CLIENTE_STOCK_ID,
      nombreEmpresa: "Europea de Maquinaria – Maquinaria Nueva",
      nombreFiscal: "Europea de Maquinaria – Maquinaria Nueva",
      cif: "B98527583",
      localidad: "Torrent (Valencia)",
      esPropia: true,
      esStockInterno: true,
      contactos: [],
      maquinas: [],
      notas: "Cliente interno — stock de maquinaria nueva pendiente de venta."
    }, ...clientes];
  }
  // Migrar data.stock[] si todavía existe
  const stock = d.stock||[];
  if (stock.length === 0) return {...d, clientes};
  const cStock = clientes.find(c=>c.id===CLIENTE_STOCK_ID);
  const existingIds = new Set((cStock.maquinas||[]).map(m=>m._stockId).filter(Boolean));
  const toMigrate = stock.filter(s=>!existingIds.has(s.id));
  const nuevasMaquinas = [
    ...(cStock.maquinas||[]),
    ...toMigrate.map(s=>({
      id: s.id,
      _stockId: s.id,
      nombre: (`${s.marca||""} ${s.modelo||""}`).trim(),
      marca: s.marca||"",
      modelo: s.modelo||"",
      serie: s.matricula||"",
      anyo: s.anyo||"",
      codigos: s.codigos||[],
      precioCompra: s.precioCompra||0,
      precioVentaObj: s.precioVentaObj||0,
      fotos: s.fotos||[],
      pdfs: s.pdfs||[],
      notas: s.notas||"",
      codigo: s.codigo||null,
    }))
  ];
  clientes = clientes.map(c=>c.id===CLIENTE_STOCK_ID?{...c,maquinas:nuevasMaquinas}:c);
  return {...d, clientes, stock:[]};
};
// Consumibles "clave" que deben tener siempre su recuadro de stock en Inventario,
// código fijo INV0001..INV0009 (en este orden) y una estrella que los distinga en el
// listado. Si una instalación ya tenía datos en el servidor sin estos artículos (o con
// la lista anterior de 6 colas), se migran aquí automáticamente en vez de obligar a
// tocarlos a mano: se eliminan los que ya no están en esta lista, se crean/actualizan
// los 9 con su código fijo, y el resto de artículos existentes se renumera de forma
// secuencial a partir de INV0010 (conservando su id interno, así no se rompen las
// referencias por id desde partes/albaranes/historial).
const CONSUMIBLES_CLAVE_NOMBRES = [
  "Caja cola natural 15 kg HKP21",
  "Caja transparente 15 kg HKP20",
  "Caja blanca 15 kg HKP21 White",
  "Saco cola natural 25 kg KS220/1",
  "Saco cola transparente 25 kg KS351",
  "Saco cola blanco 25 kg KS351 White",
  "Saco cola baja temperatura KS224/2",
  "Líquido antiadherente LC2/10",
  "Líquido limpiador máquina LC2/30",
];
const backfillConsumiblesClave = (d) => {
  const inv = d.inventario || [];
  let changed = false;
  // 1) Quitar los consumibles clave antiguos que ya no están en la lista vigente
  //    (p.ej. la anterior tanda de "cola cartucho/saco" sustituida por esta).
  let nuevoInv = inv.filter(it => {
    if (it.consumibleClave && !CONSUMIBLES_CLAVE_NOMBRES.includes(it.nombre)) { changed = true; return false; }
    return true;
  });
  // 2) Asegurar que existen los 9 vigentes, marcados como consumibleClave, con su
  //    código fijo INV0001..INV0009 según su posición en la lista.
  let nextId = Date.now();
  CONSUMIBLES_CLAVE_NOMBRES.forEach((nombre, i) => {
    const codigoFijo = "INV" + String(i + 1).padStart(4, "0");
    const existente = nuevoInv.find(it => it.nombre === nombre);
    if (!existente) {
      changed = true;
      nuevoInv = [...nuevoInv, {id:nextId++, codigo:codigoFijo, nombre, descripcion:nombre, categoria:"Cola", unidad:"ud", stock:0, stockMin:5, precioCompra:0, precioVenta:0, consumibleClave:true}];
    } else if (existente.codigo !== codigoFijo || !existente.consumibleClave) {
      changed = true;
      nuevoInv = nuevoInv.map(it => it===existente ? {...it, codigo:codigoFijo, consumibleClave:true} : it);
    }
  });
  // 3) Renumerar el resto de artículos (no consumibles clave) secuencialmente desde
  //    INV0010, en su orden actual, sin tocar su id.
  let n = 10;
  nuevoInv = nuevoInv.map(it => {
    if (it.consumibleClave) return it;
    const codigoFijo = "INV" + String(n).padStart(4, "0");
    n += 1;
    if (it.codigo === codigoFijo) return it;
    changed = true;
    return {...it, codigo: codigoFijo};
  });
  return changed ? {...d, inventario: nuevoInv} : d;
};
// Migra claves faltantes en data.contabilidad para compatibilidad con versiones antiguas.
// Cuando el servidor devuelve datos guardados antes de añadir ciertas claves (presupuestos,
// gastos, pedidos, costesVentas), esas claves llegan como undefined. Esta función las rellena
// para que el componente Contabilidad nunca reciba un objeto incompleto.
const migrateContabilidad = (d) => {
  if (!d.contabilidad) return d;
  const c = d.contabilidad;
  const defaults = { facturas:[], proformas:[], presupuestos:[], gastos:[], pedidos:[], asientos:[], tarifas:{precioPorKm:0.35,precioHoraDesplazamiento:30,precioHoraManoObra:55}, costesVentas:{} };
  let changed = false;
  const next = {};
  for (const k of Object.keys(defaults)) { if (c[k] === undefined) { next[k] = defaults[k]; changed = true; } }
  if (!changed) return d;
  return { ...d, contabilidad: { ...defaults, ...c } };
};
// Cierra automáticamente los avisos cuyo parte vinculado ya está Finalizado pero
// el save de la sección "avisos" no llegó a completarse (p.ej. el técnico cerró
// la app justo tras guardar el parte). Se ejecuta en cada carga y pull.
const repararEstadosAvisos = (d) => {
  if (!d.partes || !d.avisos) return d;
  // Cierra el aviso si el parte está Finalizado O si el email fue enviado
  // (emailEnviado cubre casos donde estadoParte no se guardó correctamente)
  const finalizados = d.partes.filter(p =>
    p.avisoId && (p.estadoParte === "Finalizado" || p.emailEnviado === true)
  );
  if (finalizados.length === 0) return d;
  let changed = false;
  const nuevosAvisos = d.avisos.map(a => {
    if (a.estado === "Resuelto" || a.estado === "Cancelado") return a;
    const parte = finalizados.find(p => String(p.avisoId) === String(a.id));
    if (!parte) return a;
    changed = true;
    return { ...a, estado: "Resuelto", fechaResuelto: parte.fecha || a.fechaResuelto, fechaUltimaIntervencion: parte.fecha || a.fechaUltimaIntervencion };
  });
  return changed ? { ...d, avisos: nuevosAvisos } : d;
};
// Función que aplica todas las migraciones/backfills al cargar datos.
const prepararDatos = d => repararEstadosAvisos(migrateContabilidad(backfillConsumiblesClave(backfillCodigosMaquina(migrateStockToCliente(d)))));

// ── Verifactu: hash SHA-256 encadenado (RD 1007/2023, Ley 11/2021 antifraude) ──
// Campos: IDEmisorFactura & NumSerieFactura & FechaExpedicion & TipoFactura & CuotaTotal & ImporteTotal & HuellaAnterior
async function computarHashVerifactu(factura, hashAnterior, nifEmisor) {
  try {
    const fecha = factura.fecha
      ? new Date(factura.fecha + "T00:00:00").toLocaleDateString("es-ES", {day:"2-digit",month:"2-digit",year:"numeric"}).replace(/\//g,"-")
      : "";
    const str = `IDEmisorFactura=${nifEmisor}&NumSerieFactura=${factura.numero}&FechaExpedicionFactura=${fecha}&TipoFactura=F1&CuotaTotal=${(parseNum(factura.cuotaIVA)||0).toFixed(2)}&ImporteTotal=${(parseNum(factura.total)||0).toFixed(2)}&HuellaAnterior=${hashAnterior}`;
    const encoded = new TextEncoder().encode(str);
    const hashBuf = await crypto.subtle.digest("SHA-256", encoded);
    return Array.from(new Uint8Array(hashBuf)).map(b=>b.toString(16).padStart(2,"0")).join("").toUpperCase();
  } catch(e) { return ""; }
}

// CSV parser para importar datos de ContaPlus / Factusol / genérico PGC
function parsearCSVContabilidad(text) {
  const firstLine = text.split("\n")[0];
  const sep = firstLine.includes(";") ? ";" : firstLine.includes("\t") ? "\t" : ",";
  const raw = text.trim().split("\n").map(l => l.split(sep).map(s => s.replace(/^["'\s]+|["'\s]+$/g,"").trim()));
  if (raw.length < 2) return null;
  const hdrs = raw[0].map(h => h.toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g,"").replace(/\s+/g," "));
  const rows = raw.slice(1).filter(r => r.some(c => c.trim()));
  const fc = (...cands) => { for(const c of cands){const i=hdrs.findIndex(h=>h.includes(c));if(i>=0)return i;} return -1; };
  const cA=fc("asiento","num asiento","numero asiento","n. asiento","nº asiento","n asiento");
  const cF=fc("fecha");
  const cC=fc("subcuenta","cuenta");
  const cN=fc("nombre cuenta","nombre subcuenta","nombre");
  const cCon=fc("concepto","descripcion","descripcion","concepto movimiento");
  const cD=fc("debe","importe debe");
  const cH=fc("haber","importe haber");
  const parseNum=s=>parseFloat((s||"").replace(/\./g,"").replace(",","."))||0;
  const parseDateES=s=>{if(!s)return"";const p=s.split(/[\/\-\.]/);if(p.length===3){if(p[0].length===4)return`${p[0]}-${p[1].padStart(2,"0")}-${p[2].padStart(2,"0")}`;return`${p[2]}-${p[1].padStart(2,"0")}-${p[0].padStart(2,"0")}`;}return s;};
  const grupos={};
  rows.forEach((row,ri)=>{
    const na=cA>=0?row[cA]:(ri+1).toString();
    const fecha=cF>=0?parseDateES(row[cF]):"";
    const cta=cC>=0?row[cC].substring(0,9):"";
    const nom=cN>=0?row[cN]:"";
    const concepto=cCon>=0?row[cCon]:"";
    const debe=cD>=0?parseNum(row[cD]):0;
    const haber=cH>=0?parseNum(row[cH]):0;
    if(!grupos[na])grupos[na]={num:na,fecha,concepto,lineas:[]};
    if(!grupos[na].fecha&&fecha)grupos[na].fecha=fecha;
    if(!grupos[na].concepto&&concepto)grupos[na].concepto=concepto;
    if(cta||debe||haber)grupos[na].lineas.push({cta,nom,debe,haber});
  });
  return Object.values(grupos).filter(g=>g.lineas.length>0);
}
// Fusión inteligente de los datos al detectar que otro dispositivo guardó mientras
// nosotros teníamos una edición local pendiente. Como "data" es un único bloque
// compartido por toda la app, antes simplemente se descartaba TODA nuestra edición
// y se avisaba con un mensaje, aunque el cambio remoto fuera en una sección totalmente
// distinta (p.ej. alguien tocó Inventario mientras nosotros editábamos una Tarea).
// Esta función compara, sección por sección y registro por registro (por id), lo que
// teníamos antes (base = lastSynced), lo que tenemos ahora (local) y lo que hay ya en
// el servidor (remoto): lo que no hemos tocado se toma del remoto sin avisar; lo que
// hemos tocado y nadie más ha tocado se mantiene nuestro sin avisar; solo si AMBOS
// lados cambiaron exactamente el mismo dato se considera un conflicto real (se prioriza
// nuestra edición, pero se devuelve en "conflictos" para poder avisar solo en ese caso).
const mismoJSON = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const combinarDatosRemotos = (base, local, remoto, ruta, conflictos) => {
  if (mismoJSON(local, base)) return remoto; // no lo tocamos -> manda el remoto
  if (mismoJSON(local, remoto)) return remoto; // el remoto ya tiene lo mismo que nosotros
  if (Array.isArray(local) && Array.isArray(remoto)) {
    const conIds = local.every(x => x && typeof x === "object" && "id" in x) && remoto.every(x => x && typeof x === "object" && "id" in x);
    if (conIds) {
      const baseArr = Array.isArray(base) ? base : [];
      const baseById = new Map(baseArr.map(x => [x.id, x]));
      const localById = new Map(local.map(x => [x.id, x]));
      const resultado = [];
      const vistos = new Set();
      for (const itemR of remoto) {
        vistos.add(itemR.id);
        const itemB = baseById.get(itemR.id);
        const itemL = localById.get(itemR.id);
        if (!itemL) {
          // Si ya lo teníamos en base y ha desaparecido de nuestra copia local, es que
          // lo hemos borrado nosotros explícitamente: ese borrado se respeta siempre,
          // aunque el remoto lo haya modificado mientras tanto (antes solo se respetaba
          // si el remoto seguía exactamente igual que en "base", y si alguien lo tocó
          // -aunque fuera un cambio mínimo, p.ej. desde otra pestaña- el borrado se
          // descartaba y el registro reaparecía). Si no estaba en "base" es que es
          // nuevo en el remoto (no lo hemos borrado, nunca lo tuvimos) y sí se incorpora.
          if (itemB) continue;
          resultado.push(itemR); // nuevo en el remoto, no relacionado con un borrado nuestro
          continue;
        }
        if (itemB && mismoJSON(itemL, itemB)) { resultado.push(itemR); continue; } // no tocamos este registro
        resultado.push(combinarDatosRemotos(itemB, itemL, itemR, ruta + "." + itemR.id, conflictos));
      }
      for (const itemL of local) {
        if (!vistos.has(itemL.id) && !baseById.has(itemL.id)) resultado.push(itemL); // creado por nosotros
      }
      return resultado;
    }
    // Array sin id identificable: no podemos fusionar con seguridad elemento a elemento.
    if (!mismoJSON(base, remoto)) conflictos.push(ruta);
    return local;
  }
  if (local && remoto && typeof local === "object" && typeof remoto === "object" && !Array.isArray(local) && !Array.isArray(remoto)) {
    const resultado = { ...remoto };
    const claves = new Set([...Object.keys(local), ...Object.keys(remoto)]);
    for (const k of claves) {
      resultado[k] = combinarDatosRemotos(base ? base[k] : undefined, local[k], remoto[k], ruta + "." + k, conflictos);
    }
    return resultado;
  }
  // Valor simple: si el remoto también cambió desde la base, es un conflicto real
  // (ambos lados cambiaron el mismo dato a la vez); priorizamos nuestra edición.
  if (!mismoJSON(base, remoto)) conflictos.push(ruta);
  return local;
};
// Geocodificación de direcciones de cliente usando Nominatim (OpenStreetMap), gratuito
// y sin API key. El resultado se cachea en el propio cliente (campos lat/lng) para no
// repetir la consulta — Nominatim limita el uso a ~1 petición/segundo.
const direccionCliente = (c) => [c.dirFiscal, c.cpFiscal, c.localidad, c.provinciaFiscal].filter(Boolean).join(", ");
// Para el mapa de máquinas siempre se prioriza la dirección de fábrica/instalación
// sobre la fiscal cuando existan ambas y sean distintas (las máquinas suelen estar
// en la nave/fábrica del cliente, no en su domicilio fiscal/administrativo). Además de
// la dirección completa, guarda el código postal y la provincia correspondientes a esa
// misma fuente (fábrica o fiscal) para poder usarlos como búsqueda de respaldo.
const datosMapaCliente = (c) => {
  const fab = [c.dirFabrica, c.cpFabrica, c.localidadFabrica, c.provinciaFabrica].filter(Boolean).join(", ");
  if (fab) return { dir: fab, cp: c.cpFabrica||"", provincia: c.provinciaFabrica||"" };
  return { dir: direccionCliente(c), cp: c.cpFiscal||"", provincia: c.provinciaFiscal||"" };
};
const direccionMapaCliente = (c) => datosMapaCliente(c).dir;
const geocodificarDireccion = async (direccion) => {
  try {
    const url = `https://nominatim.openstreetmap.org/search?format=json&limit=1&q=${encodeURIComponent(direccion+", España")}`;
    const res = await fetch(url, { headers: { "Accept":"application/json" } });
    const arr = await res.json();
    if (arr && arr[0]) return { lat: parseFloat(arr[0].lat), lng: parseFloat(arr[0].lon) };
  } catch(e) {}
  return null;
};
// Intenta localizar al cliente probando, en orden, la dirección completa, luego solo
// el código postal y, si tampoco hay resultado, solo la provincia — así un cliente con
// una dirección mal escrita o muy poco común al menos aparece (de forma aproximada)
// en el mapa en vez de no aparecer nunca. Devuelve también el nivel de precisión
// alcanzado para poder avisar en el mapa cuando la ubicación es solo aproximada.
const geocodificarConFallback = async (c) => {
  const { dir, cp, provincia } = datosMapaCliente(c);
  if (!dir) return null;
  let r = await geocodificarDireccion(dir);
  if (r) return { ...r, precision: "exacta" };
  if (cp) {
    await new Promise(res=>setTimeout(res,1100));
    r = await geocodificarDireccion(cp);
    if (r) return { ...r, precision: "cp" };
  }
  if (provincia) {
    await new Promise(res=>setTimeout(res,1100));
    r = await geocodificarDireccion(provincia);
    if (r) return { ...r, precision: "provincia" };
  }
  return null;
};
