// Componente para inputs numéricos en formato español: "." = miles, "," = decimal
// Ej: 45.000 = 45000 | 45,50 = 45.5 | 1.234,56 = 1234.56
const NumInputES = ({value, onChange, placeholder, style}) => {
  const fmtES = v => {
    if(v===null||v===undefined||v==="") return "";
    const n = typeof v==="number" ? v : parseNum(v);
    if(isNaN(n)) return "";
    return n.toLocaleString("es-ES",{minimumFractionDigits:0,maximumFractionDigits:2});
  };
  const [disp,setDisp] = React.useState(()=>fmtES(value));
  const [hasFocus,setHasFocus] = React.useState(false);
  React.useEffect(()=>{ if(!hasFocus) setDisp(fmtES(value)); },[value,hasFocus]);
  return <input type="text" inputMode="decimal" value={disp} style={style||inputStyle} placeholder={placeholder||""}
    onFocus={()=>setHasFocus(true)}
    onChange={e=>{const raw=e.target.value.replace(/[^\d.,]/g,"");setDisp(raw);onChange({...e,target:{...e.target,value:raw}});}}
    onBlur={e=>{setHasFocus(false);const f=fmtES(disp);setDisp(f);onChange({...e,target:{...e.target,value:f}});}}/>;
};
const Input = ({ value, onChange, type="text", placeholder="" }) => {
  if(type==="number") return <NumInputES value={value??""} onChange={onChange} placeholder={placeholder}/>;
  return <input type={type} value={value||""} onChange={onChange} placeholder={placeholder} style={inputStyle}/>;
};
const Select = ({ value, onChange, options }) => <select value={value} onChange={onChange} style={{...inputStyle}}>{options.map(o=><option key={o} value={o}>{o}</option>)}</select>;
// Selector de varios tecnicos a la vez (chips toggle) — para avisos/partes que realizan 2+ personas
const SelectorTecnicos = ({ value, onChange, usuarios }) => {
  const sel = Array.isArray(value) ? value : (value ? [value] : []);
  const toggle = (nombre) => onChange(sel.includes(nombre) ? sel.filter(n => n !== nombre) : [...sel, nombre]);
  return (
    <div style={{display:"flex",flexWrap:"wrap",gap:6}}>
      {usuarios.map(u => {
        const on = sel.includes(u.nombre);
        return (
          <button key={u.id} type="button" onClick={() => toggle(u.nombre)}
            style={{padding:"6px 12px",borderRadius:20,border:"2px solid "+(on?"#3b82f6":"#2a3550"),background:on?"#3b82f615":"#0d1117",color:on?"#3b82f6":"#e4e9f6",fontWeight:700,cursor:"pointer",fontSize:12,display:"flex",alignItems:"center",gap:5}}>
            {on && <Icon name="check" size={11} />}{u.nombre}
          </button>
        );
      })}
      {sel.length === 0 && <span style={{color:"#e4e9f6",fontSize:11,alignSelf:"center"}}>Sin asignar</span>}
    </div>
  );
};
const AlbaranReceptorPicker = ({ clientes, value, email, direccion, onChange }) => {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  useEffect(() => {
    const h = e => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener("mousedown", h); return () => document.removeEventListener("mousedown", h);
  }, []);
  const clientesReales = clientes.filter(c => !c.esPropia);
  const filtrados = value.trim().length === 0 ? clientesReales.slice(0, 8) :
    clientesReales.filter(c => { const q = value.toLowerCase(); return c.nombreEmpresa?.toLowerCase().includes(q) || c.nombreFiscal?.toLowerCase().includes(q) || c.cif?.toLowerCase().includes(q) || c.localidad?.toLowerCase().includes(q); }).slice(0, 10);
  return (
    <div ref={ref} style={{position:"relative"}}>
      <div style={{position:"relative"}}>
        <span style={{position:"absolute",left:9,top:"50%",transform:"translateY(-50%)",color:"#e4e9f6",pointerEvents:"none"}}><Icon name="search" size={13}/></span>
        <input value={value} onChange={e => { onChange(e.target.value, "", ""); setOpen(true); }} onFocus={() => setOpen(true)}
          placeholder="Buscar cliente existente o escribir nombre libre..."
          style={{...inputStyle,paddingLeft:30,width:"100%",boxSizing:"border-box"}} />
      </div>
      {open && (
        <div style={{position:"absolute",top:"calc(100% + 4px)",left:0,right:0,background:"#0d1117",border:"1px solid #2a3550",borderRadius:10,zIndex:300,boxShadow:"0 8px 32px rgba(0,0,0,.6)",overflow:"hidden",maxHeight:240,overflowY:"auto"}}>
          {filtrados.length === 0 && value.trim() && <div style={{padding:"8px 13px",color:"#e4e9f6",fontSize:12}}>Sin coincidencias — se usará el nombre escrito</div>}
          {filtrados.map(c => {
            const ct = c.contactos?.find(x => x.principal) || c.contactos?.[0];
            return (
              <div key={c.id} onMouseDown={() => { onChange(c.nombreEmpresa, ct?.email || "", c.localidad || "", c.id); setOpen(false); }}
                style={{padding:"9px 13px",cursor:"pointer",borderBottom:"1px solid #1a2236"}}
                onMouseEnter={e => e.currentTarget.style.background = "#151b2a"}
                onMouseLeave={e => e.currentTarget.style.background = "transparent"}>
                <div style={{color:"#f1f3f9",fontWeight:700,fontSize:13}}>{c.nombreEmpresa}</div>
                <div style={{color:"#e4e9f6",fontSize:11}}>
                  {c.localidad && <span>{c.localidad}</span>}
                  {ct?.email && <span> · {ct.email}</span>}
                </div>
              </div>
            );
          })}
          {value.trim() && <div style={{padding:"8px 13px",color:"#0ea5e9",fontSize:12,fontWeight:600,borderTop:"1px solid #2a3550",background:"#0a0f1a"}}>Usar "{value}" como receptor</div>}
        </div>
      )}
    </div>
  );
};
