const LocalidadPicker = ({ provincia, value, onChange }) => {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  useEffect(()=>{
    const h=e=>{if(ref.current&&!ref.current.contains(e.target))setOpen(false);};
    document.addEventListener("mousedown",h);return()=>document.removeEventListener("mousedown",h);
  },[]);
  const pObj = provincia ? PROVINCIAS_ES.find(x=>x.name===provincia) : null;
  const lista = pObj ? (MUNICIPIOS_ES[pObj.code] || []) : [];
  const q=(value||"").toLowerCase();
  const filtrados=q.length>=1?lista.filter(m=>m.toLowerCase().includes(q)).slice(0,15):lista.slice(0,12);
  if(!provincia)
    return <input value={value||""} onChange={e=>onChange(e.target.value)} placeholder="Selecciona primero una provincia" disabled style={{...inputStyle,opacity:.5}}/>;
  return (
    <div ref={ref} style={{position:"relative"}}>
      <div style={{position:"relative"}}>
        <input value={value||""} onChange={e=>{onChange(e.target.value);setOpen(true);}} onFocus={()=>setOpen(true)}
          placeholder="Buscar localidad..." style={inputStyle}/>
      </div>
      {open&&filtrados.length>0&&(
        <div style={{position:"absolute",top:"calc(100% + 4px)",left:0,right:0,background:"#0d1117",border:"1px solid #2a3550",borderRadius:10,zIndex:300,boxShadow:"0 8px 32px rgba(0,0,0,.6)",overflow:"hidden",maxHeight:220,overflowY:"auto"}}>
          {filtrados.map(m=>(
            <div key={m} onMouseDown={()=>{onChange(m);setOpen(false);}}
              style={{padding:"8px 13px",cursor:"pointer",color:"#f1f3f9",fontSize:13,borderBottom:"1px solid #1a2236"}}
              onMouseEnter={e=>e.currentTarget.style.background="#151b2a"}
              onMouseLeave={e=>e.currentTarget.style.background="transparent"}>{m}</div>
          ))}
        </div>
      )}
    </div>
  );
};

const ClientePicker = ({ clientes, value, onChange, placeholder="Buscar cliente por nombre, fiscal, CIF/DNI o localidad..." }) => {
  const sel = clientes.find(c => c.id === parseInt(value)) || null;
  const [busq, setBusq] = useState(sel?.nombreEmpresa || "");
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  useEffect(() => {
    const c = clientes.find(c => c.id === parseInt(value));
    if (c) setBusq(c.nombreEmpresa);
    else if (!value) setBusq("");
  }, [value]);
  useEffect(() => {
    const h = e => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener("mousedown", h);
    return () => document.removeEventListener("mousedown", h);
  }, []);
  const filtrados = busq.trim().length === 0
    ? clientes.slice(0, 8)
    : clientes.filter(c => {
        const q = busq.toLowerCase();
        return c.nombreEmpresa?.toLowerCase().includes(q)
          || c.nombreFiscal?.toLowerCase().includes(q)
          || c.cif?.toLowerCase().includes(q)
          || c.localidad?.toLowerCase().includes(q);
      }).slice(0, 10);
  const seleccionar = c => { setBusq(c.nombreEmpresa); onChange(c.id); setOpen(false); };
  const limpiar = e => { e.stopPropagation(); setBusq(""); onChange(""); setOpen(true); };
  return (
    <div ref={ref} style={{position:"relative"}}>
      <div style={{position:"relative"}}>
        <span style={{position:"absolute",left:9,top:"50%",transform:"translateY(-50%)",color:"#e4e9f6",pointerEvents:"none"}}>
          <Icon name="search" size={13}/>
        </span>
        <input
          value={busq}
          onChange={e => { setBusq(e.target.value); onChange(""); setOpen(true); }}
          onFocus={() => setOpen(true)}
          placeholder={placeholder}
          style={{...inputStyle,paddingLeft:30,paddingRight:28,width:"100%",boxSizing:"border-box"}}
        />
        {(busq || value) && (
          <button onClick={limpiar} style={{position:"absolute",right:7,top:"50%",transform:"translateY(-50%)",background:"none",border:"none",color:"#e4e9f6",cursor:"pointer",fontSize:16,lineHeight:1,padding:0}}>×</button>
        )}
      </div>
      {/* Confirmación cliente seleccionado */}
      {sel && (
        <div style={{marginTop:4,background:"#10b98112",border:"1px solid #10b98133",borderRadius:7,padding:"5px 10px",display:"flex",alignItems:"center",gap:7}}>
          <span style={{color:"#10b981",fontSize:12}}>✓</span>
          <span style={{color:"#10b981",fontSize:12,fontWeight:700}}>{sel.nombreEmpresa}</span>
          {sel.nombreFiscal && <span style={{color:"#e4e9f6",fontSize:11}}>· {sel.nombreFiscal}</span>}
          {sel.localidad && <span style={{color:"#e4e9f6",fontSize:11}}>· {sel.localidad}</span>}
        </div>
      )}
      {/* Dropdown */}
      {open && (
        <div style={{position:"absolute",top:sel ? "calc(100% - 22px)" :"calc(100% + 4px)",left:0,right:0,background:"#0d1117",border:"1px solid #2a3550",borderRadius:10,zIndex:300,boxShadow:"0 8px 32px rgba(0,0,0,.6)",overflow:"hidden",maxHeight:260,overflowY:"auto"}}>
          {filtrados.length === 0 && (
            <div style={{padding:"10px 13px",color:"#e4e9f6",fontSize:12}}>Sin resultados para "{busq}"</div>
          )}
          {filtrados.map(c => (
            <div key={c.id} onMouseDown={() => seleccionar(c)}
              style={{padding:"9px 13px",cursor:"pointer",borderBottom:"1px solid #1a2236",display:"flex",justifyContent:"space-between",alignItems:"center",background:c.id === parseInt(value) ? "#1a2236" :"transparent"}}
              onMouseEnter={e => e.currentTarget.style.background = "#151b2a"}
              onMouseLeave={e => e.currentTarget.style.background = c.id === parseInt(value) ? "#1a2236" : "transparent"}>
              <div>
                <div style={{color:"#f1f3f9",fontWeight:700,fontSize:13}}>{c.nombreEmpresa}</div>
                <div style={{color:"#e4e9f6",fontSize:11}}>
                  {c.nombreFiscal && <span>{c.nombreFiscal}</span>}
                  {c.localidad && <span> · {c.localidad}</span>}
                </div>
              </div>
              {c.id === parseInt(value) && <span style={{color:"#10b981"}}>✓</span>}
            </div>
          ))}
          {filtrados.length > 0 && busq.trim().length > 0 && filtrados.length < clientes.filter(c=>{const q=busq.toLowerCase();return c.nombreEmpresa?.toLowerCase().includes(q)||c.nombreFiscal?.toLowerCase().includes(q)||c.cif?.toLowerCase().includes(q)||c.localidad?.toLowerCase().includes(q);}).length && (
            <div style={{padding:"6px 13px",color:"#e4e9f6",fontSize:11,fontStyle:"italic",background:"#0a0f1a"}}>Refina la búsqueda para ver más resultados</div>
          )}
        </div>
      )}
    </div>
  );
};
// --- Escaneo de tarjetas de visita (lectura con IA — Gemini, tier gratuito) ---
// La foto se envía al backend (public/api/escanear-tarjeta.php), que llama a
// la API de Gemini con la imagen y un esquema de salida; Gemini devuelve ya
// los campos repartidos (no hace falta ningún parseo heurístico por regex).
// La clave de Gemini nunca se expone en el navegador: solo vive en el
// servidor (config.php), igual que la API_KEY de la propia app.
const ASPECTO_TARJETA = 1.586; // ancho/alto estándar de una tarjeta de visita (85.6 x 54mm)

// Convierte los campos que devuelve Gemini (strings, puede traer espacios o
// venir ausentes) a la forma exacta que usan crearClienteDesdeTarjeta /
// crearClienteDesdeTarjetaVisita.
const normalizarCamposTarjetaIA = (c) => {
  if (!c || typeof c !== "object") return {};
  const limpio = v => (typeof v === "string" ? v.trim() : "");
  const campos = {
    nombreEmpresa: limpio(c.nombreEmpresa),
    nombreFiscal: limpio(c.nombreFiscal),
    contactoNombre: limpio(c.contactoNombre),
    puesto: limpio(c.puesto),
    dirFiscal: limpio(c.dirFiscal),
    cpFiscal: limpio(c.cpFiscal),
    localidad: limpio(c.localidad),
    provinciaFiscal: limpio(c.provinciaFiscal),
    tel: limpio(c.tel),
    email: limpio(c.email),
    web: limpio(c.web),
  };
  if (Array.isArray(c.telsExtra)) {
    const extra = c.telsExtra.map(limpio).filter(Boolean);
    if (extra.length) campos._telsExtra = extra;
  }
  return campos;
};

const EscanearTarjetaModal = ({ onClose, onResultado }) => {
  const [paso, setPaso] = useState("camara"); // camara | revision | procesando
  const [foto, setFoto] = useState(null);
  const [camError, setCamError] = useState("");
  const [errorOcr, setErrorOcr] = useState("");
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const streamRef = useRef(null);
  const rectRef = useRef(null);

  const detenerCamara = () => { if (streamRef.current) { streamRef.current.getTracks().forEach(t=>t.stop()); streamRef.current = null; } };

  useEffect(() => {
    if (paso !== "camara") return;
    let activo = true;
    setCamError("");
    navigator.mediaDevices?.getUserMedia({ video: { facingMode: "environment" } })
      .then(stream => {
        if (!activo) { stream.getTracks().forEach(t=>t.stop()); return; }
        streamRef.current = stream;
        if (videoRef.current) { videoRef.current.srcObject = stream; videoRef.current.play().catch(()=>{}); }
      })
      .catch(err => setCamError("No se pudo acceder a la cámara: " + (err.message || err)));
    return () => { activo = false; detenerCamara(); };
  }, [paso]);

  useEffect(() => () => detenerCamara(), []);

  // Ancho de trabajo al que se reescala la imagen recortada antes de enviarla
  // a Gemini. Recortar al recuadro guía (en vez de mandar el fotograma
  // completo con todo el fondo alrededor) sigue mereciendo la pena: menos
  // datos que enviar/procesar y la tarjeta ocupa toda la imagen. No se aplica
  // blanco y negro ni contraste artificial: un modelo de visión lee mejor la
  // foto a color tal cual, sin el preprocesado que ayudaba al OCR clásico.
  const ANCHO_OBJETIVO_IA = 1000;

  const capturar = () => {
    const video = videoRef.current;
    if (!video || !video.videoWidth) return;

    const videoRect = video.getBoundingClientRect();
    const escalaNativa = video.videoWidth / videoRect.width;
    let sx = 0, sy = 0, sw = video.videoWidth, sh = video.videoHeight;
    if (rectRef.current) {
      const guia = rectRef.current.getBoundingClientRect();
      sx = Math.max(0, (guia.left - videoRect.left) * escalaNativa);
      sy = Math.max(0, (guia.top - videoRect.top) * escalaNativa);
      sw = Math.min(video.videoWidth - sx, guia.width * escalaNativa);
      sh = Math.min(video.videoHeight - sy, guia.height * escalaNativa);
    }
    if (sw <= 0 || sh <= 0) { sx = 0; sy = 0; sw = video.videoWidth; sh = video.videoHeight; }

    const destW = ANCHO_OBJETIVO_IA;
    const destH = Math.round(destW / (sw / sh));
    const canvas = canvasRef.current;
    canvas.width = destW; canvas.height = destH;
    const ctx = canvas.getContext("2d");
    ctx.drawImage(video, sx, sy, sw, sh, 0, 0, destW, destH);

    detenerCamara();
    setFoto(canvas.toDataURL("image/jpeg", 0.92));
    setPaso("revision");
  };

  const subirFoto = e => {
    const file = e.target.files[0]; e.target.value = "";
    if (!file) return;
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      // Aquí no hay recuadro guía sobre el que recortar (es una foto ya
      // hecha), así que solo se reescala a un tamaño de trabajo razonable.
      const MAXW = 1400;
      const escala = Math.min(1, MAXW / img.naturalWidth);
      const w = Math.round(img.naturalWidth * escala), h = Math.round(img.naturalHeight * escala);
      const canvas = document.createElement("canvas");
      canvas.width = w; canvas.height = h;
      const ctx = canvas.getContext("2d");
      ctx.drawImage(img, 0, 0, w, h);
      URL.revokeObjectURL(url);
      detenerCamara();
      setFoto(canvas.toDataURL("image/jpeg", 0.92));
      setPaso("revision");
    };
    img.src = url;
  };

  const repetir = () => { setFoto(null); setErrorOcr(""); setPaso("camara"); };

  const leerTarjeta = async () => {
    setPaso("procesando"); setErrorOcr("");
    try {
      const respuesta = await apiEscanearTarjeta(foto);
      const campos = normalizarCamposTarjetaIA(respuesta.campos);
      onResultado(campos, foto, respuesta.textoCrudo || "");
    } catch (e) {
      setErrorOcr("No se ha podido leer la tarjeta: " + (e?.message || e));
      setPaso("revision");
    }
  };

  return (
    <Modal title="Escanear tarjeta de visita" onClose={onClose}>
      {paso === "camara" && (
        <>
          <div style={{background:"#000",borderRadius:10,overflow:"hidden",marginBottom:14,position:"relative",minHeight:240,display:"flex",alignItems:"center",justifyContent:"center"}}>
            {camError ? (
              <div style={{color:"#ef4444",fontSize:13,padding:20,textAlign:"center"}}>{camError}</div>
            ) : (
              <>
                <video ref={videoRef} autoPlay muted playsInline style={{width:"100%",display:"block"}}/>
                <div ref={rectRef} style={{position:"absolute",top:"50%",left:"50%",transform:"translate(-50%,-50%)",width:"82%",aspectRatio:String(ASPECTO_TARJETA),border:"2px dashed #faff00",borderRadius:10,boxShadow:"0 0 0 2000px rgba(0,0,0,.35)",pointerEvents:"none"}}/>
              </>
            )}
          </div>
          <canvas ref={canvasRef} style={{display:"none"}}/>
          <div style={{color:"#e4e9f6",fontSize:11,marginBottom:14,textAlign:"center"}}>Encuadra la tarjeta dentro del recuadro, bien iluminada y sin reflejos</div>
          <div style={{display:"flex",gap:9,justifyContent:"space-between",alignItems:"center",flexWrap:"wrap"}}>
            <label style={{color:"#3b82f6",fontSize:12,fontWeight:700,cursor:"pointer"}}>
              Subir foto en su lugar
              <input type="file" accept="image/*" capture="environment" onChange={subirFoto} style={{display:"none"}}/>
            </label>
            <div style={{display:"flex",gap:9}}>
              <button onClick={onClose} style={btnOutline}>Cancelar</button>
              <button onClick={capturar} disabled={!!camError} style={{...btnPrimary,opacity:camError?0.5:1}}>📷 Capturar</button>
            </div>
          </div>
        </>
      )}
      {paso === "revision" && (
        <>
          <div style={{background:"#000",borderRadius:10,overflow:"hidden",marginBottom:14,textAlign:"center"}}>
            <img src={foto} alt="Tarjeta capturada" style={{maxWidth:"100%",maxHeight:320,display:"block",margin:"0 auto"}}/>
          </div>
          {errorOcr && <div style={{color:"#ef4444",fontSize:12,marginBottom:12,textAlign:"center"}}>{errorOcr}</div>}
          <div style={{display:"flex",gap:9,justifyContent:"flex-end"}}>
            <button onClick={repetir} style={btnOutline}>Repetir foto</button>
            <button onClick={leerTarjeta} style={btnPrimary}>Usar esta foto</button>
          </div>
        </>
      )}
      {paso === "procesando" && (
        <div style={{textAlign:"center",padding:"30px 10px"}}>
          <div style={{fontSize:40,marginBottom:14}}>🤖</div>
          <div style={{color:"#e1e6f2",fontSize:13}}>Analizando la tarjeta con IA...</div>
        </div>
      )}
    </Modal>
  );
};

