// ─── API por secciones ───────────────────────────────────────────────────────
// GET ?action=sections → {sections:{clientes:[…], avisos:[…], config:{…}}, versions:{clientes:5,…}}
async function apiGetSecciones(){
  const res = await fetch(API_URL+"?action=sections", { headers:{"X-Api-Key":API_KEY} });
  if(!res.ok) throw new Error("GET sections "+res.status);
  return res.json();
}
// POST con X-Section: guarda solo la sección indicada con control de versión atómico.
async function apiGuardarSeccion(seccion, datos, versionEsperada, opts={}){
  const res = await fetch(API_URL, {
    method:"POST",
    headers:{
      "Content-Type":"application/json",
      "X-Api-Key":API_KEY,
      "X-Section":seccion,
      ...(typeof versionEsperada==="number" ? {"X-Expected-Version":String(versionEsperada)} : {}),
    },
    body:JSON.stringify(datos),
    ...(opts.keepalive ? {keepalive:true} : {}),
  });
  if(res.status===409){const j=await res.json().catch(()=>({}));return{conflict:true,version:j.version,section:seccion};}
  if(!res.ok) throw new Error("POST section "+res.status);
  return res.json(); // {ok:true, section, version}
}
const ESCANEAR_TARJETA_API_URL = "/api/escanear-tarjeta.php";
// Envía la foto de la tarjeta (data URL) al backend, que la pasa a Gemini y
// devuelve los campos ya extraídos: { ok, campos, textoCrudo }.
async function apiEscanearTarjeta(imagenBase64){
  const res = await fetch(ESCANEAR_TARJETA_API_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json", "X-Api-Key": API_KEY },
    body: JSON.stringify({ imagen: imagenBase64 }),
  });
  const json = await res.json().catch(()=>({}));
  if(!res.ok || json.error){
    const msg = json.error === "gemini_not_configured"
      ? "El escáner de tarjetas no está configurado en el servidor (falta la clave de Gemini)."
      : (json.detail || json.error || ("HTTP "+res.status));
    throw new Error(msg);
  }
  return json;
}
const MAIL_API_URL = "/api/send-mail.php";
async function apiSendMail(payload){
  // Nunca se envía copia a servicio@: solo cliente + gestion@europeademaquinaria.com.
  if (payload && typeof payload.cc === "string") {
    payload = {
      ...payload,
      cc: payload.cc.split(",").map(e=>e.trim()).filter(e=>e && !/^servicio@europeademaquinaria\.com$/i.test(e)).join(", "),
    };
  }
  const res = await fetch(MAIL_API_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json", "X-Api-Key": API_KEY },
    body: JSON.stringify(payload),
  });
  const json = await res.json().catch(()=>({}));
  if(!res.ok || json.error){
    const msg = json.error === "smtp_not_configured"
      ? "El SMTP no está configurado (ve a Ajustes)."
      : (json.detail || json.error || ("HTTP "+res.status));
    throw new Error(msg);
  }
  return json;
}
const UPLOAD_API_URL = "/api/upload.php";
// Carga una foto (base64 data URI o URL de servidor) como data URI listo para jsPDF.
// Las fotos nuevas se guardan como URL en el servidor; las antiguas siguen siendo base64.
async function cargarFotoParaPDF(src){
  if(!src)return null;
  if(src.startsWith("data:"))return src;
  // Usar fetch() para imágenes de servidor: evita canvas y problemas CORS.
  // Las imágenes son same-origin (/api/uploads/...) — fetch funciona sin CORS headers.
  try{
    const resp=await fetch(src);
    if(!resp.ok)throw new Error("fetch "+resp.status);
    let blob=await resp.blob();
    // ── Convertir HEIC/HEIF (formato iPhone) a JPEG antes de añadir al PDF ──
    const esHEIC=blob.type==="image/heic"||blob.type==="image/heif"||
      /\.(heic|heif)$/i.test(src);
    if(esHEIC){
      try{
        const heic2any=(await import("heic2any")).default;
        let converted=await heic2any({blob,toType:"image/jpeg",quality:0.85});
        // heic2any devuelve Blob o Blob[] según el archivo
        blob=Array.isArray(converted)?converted[0]:converted;
      }catch(heicErr){console.warn("heic2any error:",heicErr);}
    }
    return await new Promise((resolve,reject)=>{
      const reader=new FileReader();
      reader.onload=()=>resolve(reader.result);
      reader.onerror=reject;
      reader.readAsDataURL(blob);
    });
  }catch(e){
    // Fallback canvas sin crossOrigin (same-origin no mancha el canvas)
    return new Promise(resolve=>{
      const img=new Image();
      img.onload=()=>{
        try{
          const c=document.createElement("canvas");
          c.width=img.naturalWidth;c.height=img.naturalHeight;
          c.getContext("2d").drawImage(img,0,0);
          resolve(c.toDataURL("image/jpeg",0.85));
        }catch(e2){resolve(null);}
      };
      img.onerror=()=>resolve(null);
      img.src=src;
    });
  }
}
// Redimensiona y comprime una imagen en el navegador antes de subirla: las
// fotos hechas con el móvil pueden pesar varios MB (o venir en HEIC, que el
// servidor no admite). Si el navegador puede decodificarla, la reescalamos a
// un máximo de 1200px y la convertimos a JPEG de calidad aceptable.
// Si no puede decodificarla, se sube el original y el servidor decide.
async function comprimirImagen(file, maxDim = 1200, calidad = 0.78) {
  if (!file) return file;
  // Convertir HEIC/HEIF a JPEG antes de cualquier procesado (iPhone, etc.)
  // OJO: no usamos el nombre de archivo como criterio si el MIME ya dice que es
  // una imagen conocida (p.ej. iOS entrega JPEG con extensión .heic → no es HEIC).
  const mimeEsHEIC = file.type==="image/heic"||file.type==="image/heif";
  const mimeEsImgConocida = file.type && file.type.startsWith("image/") && !mimeEsHEIC;
  const esHEIC = mimeEsHEIC || (!mimeEsImgConocida && /\.(heic|heif)$/i.test(file.name));
  if (esHEIC) {
    let convertido = false;
    // Comprueba que el canvas tiene contenido real (no cuadrado negro).
    // Un canvas negro uniforme indica que el navegador aceptó el HEIC pero no lo decodificó.
    const canvasEsValido = (cv) => {
      try {
        const ctx = cv.getContext("2d");
        // Muestreamos 5 puntos: centro + cuatro cuadrantes
        const pts = [[0.25,0.25],[0.75,0.25],[0.5,0.5],[0.25,0.75],[0.75,0.75]];
        let rgbSuma = 0;
        for (const [fx,fy] of pts) {
          const d = ctx.getImageData(Math.floor(cv.width*fx), Math.floor(cv.height*fy), 1, 1).data;
          rgbSuma += d[0]+d[1]+d[2]; // Solo RGB — el alfa es 255 incluso en canvas negro opaco
        }
        // Si el brillo RGB total de los 5 puntos es casi cero → decode fallido (negro uniforme)
        return rgbSuma > 80;
      } catch(_){ return true; } // Si hay error de seguridad, aceptamos el resultado
    };
    // Método 1: createImageBitmap nativo (Safari macOS/iOS)
    try {
      const bmp = await createImageBitmap(file);
      const cv = document.createElement("canvas");
      let w = bmp.width, h = bmp.height;
      if (w > maxDim || h > maxDim) { const r = Math.min(maxDim/w, maxDim/h); w=Math.round(w*r); h=Math.round(h*r); }
      cv.width = w; cv.height = h;
      cv.getContext("2d").drawImage(bmp, 0, 0, w, h);
      if (bmp.close) bmp.close();
      if (!canvasEsValido(cv)) throw new Error("canvas negro — HEIC no decodificado");
      const blob = await new Promise(res => cv.toBlob(res, "image/jpeg", 0.85));
      if (!blob) throw new Error("toBlob null");
      file = new File([blob], file.name.replace(/\.[^.]+$/, "")+".jpg", { type:"image/jpeg" });
      convertido = true;
    } catch (_bmpErr) { console.warn("createImageBitmap HEIC:", _bmpErr.message); }
    // Método 2: <img> + canvas (iOS Safari / macOS Safari)
    if (!convertido) {
      try {
        const tempUrl = URL.createObjectURL(file);
        const img = await new Promise((res, rej) => {
          const el = new Image(); el.onload=()=>res(el); el.onerror=rej; el.src=tempUrl;
        });
        URL.revokeObjectURL(tempUrl);
        if (!img.naturalWidth || !img.naturalHeight) throw new Error("img sin dimensiones");
        const cv = document.createElement("canvas");
        let w = img.naturalWidth, h = img.naturalHeight;
        if (w > maxDim || h > maxDim) { const r = Math.min(maxDim/w, maxDim/h); w=Math.round(w*r); h=Math.round(h*r); }
        cv.width = w; cv.height = h;
        cv.getContext("2d").drawImage(img, 0, 0, w, h);
        if (!canvasEsValido(cv)) throw new Error("canvas negro — HEIC no decodificado");
        const blob = await new Promise(res => cv.toBlob(res, "image/jpeg", 0.85));
        if (!blob) throw new Error("toBlob null");
        file = new File([blob], file.name.replace(/\.[^.]+$/, "")+".jpg", { type:"image/jpeg" });
        convertido = true;
      } catch (_imgErr) { console.warn("img+canvas HEIC:", _imgErr.message); }
    }
    // Método 3: heic2any — import estático para garantizar que Vite lo bundlea correctamente
    if (!convertido) {
      try {
        let converted = await heic2any({ blob: file, toType: "image/jpeg", quality: 0.85 });
        if (Array.isArray(converted)) converted = converted[0];
        file = new File([converted], file.name.replace(/\.[^.]+$/, "")+".jpg", { type:"image/jpeg" });
        convertido = true;
      } catch (heicErr) { console.warn("heic2any fallo:", heicErr); }
    }
    if (!convertido) {
      alert("No se pudo convertir la imagen HEIC a JPEG en este navegador.\n\nSolución: abre la foto en tu galería, compártela o expórtala como JPEG, e inténtalo de nuevo.");
      return null;
    }
  }
  if (!file) return null;
  if (!file.type || !file.type.startsWith("image/") || file.type === "image/svg+xml") return file;
  let url;
  try {
    url = URL.createObjectURL(file);
    const img = await new Promise((res, rej) => {
      const el = new Image();
      el.onload = () => res(el);
      el.onerror = rej;
      el.src = url;
    });
    let w = img.naturalWidth, h = img.naturalHeight;
    if (w > maxDim || h > maxDim) {
      const ratio = Math.min(maxDim / w, maxDim / h);
      w = Math.round(w * ratio); h = Math.round(h * ratio);
    }
    const canvas = document.createElement("canvas");
    canvas.width = w; canvas.height = h;
    canvas.getContext("2d").drawImage(img, 0, 0, w, h);
    const blob = await new Promise(res => canvas.toBlob(res, "image/jpeg", calidad));
    if (!blob) throw new Error("canvas.toBlob devolvió null");
    const nombre = file.name.replace(/\.[^.]+$/, "") + ".jpg";
    return new File([blob], nombre, { type: "image/jpeg" });
  } catch (e) {
    // Si el canvas no pudo procesar la imagen (p.ej. HEIC en Chrome),
    // intentamos devolver una versión con tipo forzado a image/jpeg para que
    // el servidor la acepte igualmente. Si el archivo original ya es JPEG, se
    // devuelve tal cual.
    if (file.type === "image/jpeg" || file.type === "image/jpg") return file;
    // Para otros formatos que no son renderizables, devolvemos el archivo original;
    // el servidor lo rechazará con error claro si el formato no está permitido.
    return file;
  } finally {
    if (url) URL.revokeObjectURL(url);
  }
}
async function apiUploadFile(payload){
  const res = await fetch(UPLOAD_API_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json", "X-Api-Key": API_KEY },
    body: JSON.stringify(payload),
  });
  const json = await res.json().catch(()=>({}));
  if(!res.ok || json.error || !json.url){
    const msgs = { tipo_no_permitido:"Tipo de archivo no permitido.", archivo_demasiado_grande:"El archivo pesa demasiado (máx. 25 MB).", missing_fields:"Datos incompletos al subir.", no_se_pudo_guardar:"No se pudo guardar en el servidor." };
    throw new Error(msgs[json.error] || json.error || (!json.url ? "El servidor no devolvió URL del archivo." : "") || ("HTTP "+res.status));
  }
  return json;
}

// Modal de encuadre/recorte de foto de perfil: permite arrastrar para reposicionar
// y un deslizador de zoom, de forma que la foto final sea siempre cuadrada y bien
// centrada antes de guardarla (evita que luego se vea cortada en el avatar circular).
const FotoCropModal = ({ source, onCancel, onSave }) => {
  const VIEW = 260; // tamaño del visor circular en pantalla (px)
  const OUT = 480;  // resolución de la imagen final guardada (px)
  const [img, setImg] = useState(null);
  const [zoom, setZoom] = useState(1);
  const [minZoom, setMinZoom] = useState(0.5);
  const [pos, setPos] = useState({ x: 0, y: 0 });
  const dragRef = useRef(null);
  const baseScaleRef = useRef(1);

  useEffect(() => {
    // source puede ser un File recién elegido o ya un data URL (al reencuadrar una foto existente)
    let url, cancelado = false;
    const esFile = source instanceof File || source instanceof Blob;
    const el = new Image();
    el.onload = () => {
      if (cancelado) return;
      const ratioW = VIEW / el.naturalWidth, ratioH = VIEW / el.naturalHeight;
      const base = Math.max(ratioW, ratioH); // escala mínima que cubre todo el visor sin huecos
      const contain = Math.min(ratioW, ratioH); // escala a la que se ve la foto entera
      baseScaleRef.current = base;
      const minZ = Math.min(1, Math.max(0.15, contain / base));
      setMinZoom(minZ);
      setImg(el);
      setZoom(1);
      setPos({ x: (VIEW - el.naturalWidth * base) / 2, y: (VIEW - el.naturalHeight * base) / 2 });
    };
    if (esFile) { url = URL.createObjectURL(source); el.src = url; }
    else el.src = source;
    return () => { cancelado = true; if (url) URL.revokeObjectURL(url); };
  }, [source]);

  // Si la foto, al hacer zoom, queda más pequeña que el visor, se centra (en vez
  // de quedar pegada a una esquina); si es más grande, se limita para que no
  // se salga del marco. En ambos casos se escala igual en ancho y alto, así
  // que la proporción de la foto nunca se deforma.
  const clampAxis = (p, size) => size <= VIEW ? (VIEW - size) / 2 : Math.min(0, Math.max(p, VIEW - size));
  const clamp = (p, z) => {
    if (!img) return p;
    const w = img.naturalWidth * baseScaleRef.current * z;
    const h = img.naturalHeight * baseScaleRef.current * z;
    return { x: clampAxis(p.x, w), y: clampAxis(p.y, h) };
  };
  const onPointerDown = e => { dragRef.current = { sx: e.clientX, sy: e.clientY, ox: pos.x, oy: pos.y }; e.target.setPointerCapture?.(e.pointerId); };
  const onPointerMove = e => {
    if (!dragRef.current) return;
    const d = dragRef.current;
    setPos(clamp({ x: d.ox + (e.clientX - d.sx), y: d.oy + (e.clientY - d.sy) }, zoom));
  };
  const onPointerUp = () => { dragRef.current = null; };
  const handleZoom = e => { const z = parseFloat(e.target.value); setZoom(z); setPos(p => clamp(p, z)); };

  const guardar = () => {
    if (!img) return;
    const canvas = document.createElement("canvas");
    canvas.width = OUT; canvas.height = OUT;
    const ctx = canvas.getContext("2d");
    ctx.fillStyle = "#0d1117";
    ctx.fillRect(0, 0, OUT, OUT);
    const f = OUT / VIEW;
    const w = img.naturalWidth * baseScaleRef.current * zoom * f;
    const h = img.naturalHeight * baseScaleRef.current * zoom * f;
    ctx.drawImage(img, pos.x * f, pos.y * f, w, h);
    canvas.toBlob(blob => {
      if (!blob) return;
      const r = new FileReader();
      r.onload = ev => onSave(ev.target.result);
      r.readAsDataURL(blob);
    }, "image/jpeg", 0.88);
  };

  return (
    <Modal title="Encuadrar foto de perfil" onClose={onCancel}>
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 16 }}>
        <div
          onPointerDown={onPointerDown} onPointerMove={onPointerMove} onPointerUp={onPointerUp} onPointerLeave={onPointerUp}
          style={{ width: VIEW, height: VIEW, borderRadius: "50%", overflow: "hidden", position: "relative", background: "#0d1117", border: "2px solid #2a3550", cursor: img ? "grab" : "default", touchAction: "none" }}
        >
          {img && (
            <img src={img.src} draggable={false} alt=""
              style={{ position: "absolute", left: pos.x, top: pos.y, width: img.naturalWidth * baseScaleRef.current * zoom, height: img.naturalHeight * baseScaleRef.current * zoom, userSelect: "none", pointerEvents: "none" }} />
          )}
        </div>
        <div style={{ width: "100%", maxWidth: 280 }}>
          <div style={{ fontSize: 11, fontWeight: 700, color: "#e4e9f6", textTransform: "uppercase", letterSpacing: ".7px", marginBottom: 6, textAlign: "center" }}>Zoom</div>
          <input type="range" min={minZoom} max="3" step="0.01" value={zoom} onChange={handleZoom} style={{ width: "100%" }} />
        </div>
        <div style={{ color: "#e4e9f6", fontSize: 11.5, textAlign: "center" }}>Arrastra la foto para encuadrarla y usa el deslizador para hacer zoom.</div>
      </div>
      <div style={{ display: "flex", gap: 10, justifyContent: "flex-end", marginTop: 18 }}>
        <button onClick={onCancel} style={btnOutline}>Cancelar</button>
        <button onClick={guardar} style={btnPrimary}>Usar esta foto</button>
      </div>
    </Modal>
  );
};
const MiCuenta = ({ userActual, setData, onUpdateUser, onClose }) => {
  const [foto, setFoto] = useState(userActual.foto || null);
  const [email, setEmail] = useState(userActual.email || "");
  const [telefono, setTelefono] = useState(userActual.telefono || "");
  const [puesto, setPuesto] = useState(userActual.puesto || "");
  const [pass1, setPass1] = useState("");
  const [pass2, setPass2] = useState("");
  const [err, setErr] = useState("");
  const [ok, setOk] = useState("");
  const [cropSource, setCropSource] = useState(null);
  const handleFoto = e => {
    const f0 = e.target.files[0]; if (!f0) return;
    setCropSource(f0);
    e.target.value = "";
  };
  const guardar = () => {
    if (pass1 && pass1.length < 4) { setErr("La contraseña debe tener al menos 4 caracteres."); return; }
    if (pass1 && pass1 !== pass2) { setErr("Las contraseñas no coinciden."); return; }
    setErr("");
    const cambios = { foto, email: email.trim(), telefono: telefono.trim(), puesto: puesto.trim() };
    if (pass1) cambios.password = pass1;
    setData(d => ({ ...d, usuarios: d.usuarios.map(u => u.id === userActual.id ? { ...u, ...cambios } : u) }));
    onUpdateUser(prev => ({ ...prev, ...cambios }));
    setPass1(""); setPass2("");
    setOk("Cambios guardados.");
    setTimeout(() => setOk(""), 2500);
  };
  return (
    <>
    <Modal title="Mi cuenta" onClose={onClose}>
      <div style={{ display: "flex", alignItems: "center", gap: 14, marginBottom: 18, flexWrap: "wrap" }}>
        <Avatar u={{ ...userActual, foto }} size={64} fontSize={22} />
        <div>
          <div style={{ color: "#f1f3f9", fontWeight: 700, fontSize: 15 }}>{userActual.nombre}</div>
          <div style={{ margin: "4px 0 8px" }}><RolBadge rol={userActual.rol} /></div>
          <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
            <label style={{ display: "inline-flex", alignItems: "center", gap: 6, background: "#2a3550", color: "#e1e6f2", border: "1px solid #3a4560", borderRadius: 8, padding: "6px 12px", cursor: "pointer", fontSize: 12, fontWeight: 600 }}>
              <Icon name="image" size={13} />{foto ? "Cambiar foto" : "Subir foto"}
              <input type="file" accept="image/*" onChange={handleFoto} style={{ display: "none" }} />
            </label>
            {foto && <button onClick={() => setCropSource(foto)} style={{ ...btnSm("#2a3550", "#e1e6f2"), fontSize: 11 }}>Editar encuadre</button>}
            {foto && <button onClick={() => setFoto(null)} style={{ ...btnSm("#3b1c1c", "#dc2626"), fontSize: 11 }}>Quitar foto</button>}
          </div>
        </div>
      </div>
      <div style={{ borderTop: "1px solid #2a3550", paddingTop: 14, marginBottom: 14 }}>
        <div style={{ fontSize: 11, fontWeight: 700, color: "#e4e9f6", textTransform: "uppercase", letterSpacing: ".7px", marginBottom: 10 }}>Contacto</div>
        <Field label="Email (para recibir avisos de tareas)"><Input type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="tu@europeademaquinaria.com" /></Field>
        <div style={{ color: "#e4e9f6", fontSize: 11.5, marginTop: 5, marginBottom: 14 }}>Si lo rellenas, recibirás un email cada vez que se te asigne una tarea nueva.</div>
        <Field label="Teléfono (opcional)"><Input type="tel" value={telefono} onChange={e => setTelefono(e.target.value)} placeholder="600 000 000" /></Field>
        <div style={{ color: "#e4e9f6", fontSize: 11.5, marginTop: 5, marginBottom: 14 }}>Aparecerá en la firma de los emails de tareas que envíes o reenvíes.</div>
        <Field label="Puesto (opcional)"><Input value={puesto} onChange={e => setPuesto(e.target.value)} placeholder="Ej: Director comercial" /></Field>
        <div style={{ color: "#e4e9f6", fontSize: 11.5, marginTop: 5 }}>También aparecerá en la firma de tus emails, debajo de tu nombre.</div>
      </div>
      <div style={{ borderTop: "1px solid #2a3550", paddingTop: 14 }}>
        <div style={{ fontSize: 11, fontWeight: 700, color: "#e4e9f6", textTransform: "uppercase", letterSpacing: ".7px", marginBottom: 10 }}>Cambiar contraseña</div>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill,minmax(min(220px,100%),1fr))", gap: 11 }}>
          <Field label="Nueva contraseña"><Input type="password" value={pass1} onChange={e => setPass1(e.target.value)} placeholder="Dejar en blanco para no cambiar" /></Field>
          <Field label="Confirmar contraseña"><Input type="password" value={pass2} onChange={e => setPass2(e.target.value)} /></Field>
        </div>
      </div>
      {err && <div style={{ color: "#ef4444", fontSize: 12, marginTop: 10 }}>{err}</div>}
      {ok && <div style={{ color: "#10b981", fontSize: 12, marginTop: 10 }}>{ok}</div>}
      <div style={{ display: "flex", gap: 10, justifyContent: "flex-end", marginTop: 18 }}>
        <button onClick={onClose} style={btnOutline}>Cerrar</button>
        <button onClick={guardar} style={btnPrimary}>Guardar</button>
      </div>
    </Modal>
    {cropSource && <FotoCropModal source={cropSource} onCancel={() => setCropSource(null)} onSave={async dataUrl => { try{const b64=dataUrl.split(",")[1];const up=await apiUploadFile({base64:b64,filename:"avatar.jpg",mime:"image/jpeg"});setFoto(up.url);}catch(er){setFoto(dataUrl);}setCropSource(null); }} />}
    </>
  );
};

// ── FICHA PÚBLICA DE ARTÍCULO (sin login, accesible escaneando el QR) ──────
const FichaPublicaArticulo = ({ codigo, data, cargando }) => {
  const item = data?.inventario?.find(i => i.codigo === codigo);
  return (
    <div style={{minHeight:"100vh",background:"#0d1117",color:"#f1f3f9",fontFamily:"Arial,sans-serif",display:"flex",flexDirection:"column",alignItems:"center",padding:"0 0 30px"}}>
      <div style={{width:"100%",background:"#151b2a",borderBottom:"2px solid #a855f733",padding:"20px 16px 16px",textAlign:"center"}}>
        <div style={{fontSize:10,color:"#a855f7",letterSpacing:2,textTransform:"uppercase",fontWeight:700,marginBottom:6}}>Europea de Maquinaria PMM SL</div>
        <div style={{fontSize:13,color:"#e4e9f6"}}>Ficha de artículo</div>
      </div>
      <div style={{width:"100%",maxWidth:420,padding:"20px 16px"}}>
        {!item ? (
          <div style={{textAlign:"center",color:"#e4e9f6",padding:"40px 10px"}}>
            {cargando ? "Cargando artículo..." : (
              <>
                <div style={{fontSize:36,marginBottom:10}}>❓</div>
                <div style={{fontWeight:700,color:"#f1f3f9",marginBottom:4}}>Artículo no encontrado</div>
                <div style={{fontSize:13}}>No existe ningún artículo con el código "{codigo}".</div>
              </>
            )}
          </div>
        ) : (
          <>
            {item.foto && <img src={item.foto} alt={item.nombre} style={{width:"100%",maxHeight:220,objectFit:"cover",borderRadius:12,border:"1px solid #2a3550",marginBottom:14}}/>}
            <div style={{textAlign:"center",marginBottom:16}}>
              <div style={{fontSize:26,fontWeight:900,letterSpacing:3,color:"#a855f7"}}>{item.codigo}</div>
              <div style={{fontSize:16,fontWeight:700,marginTop:4}}>{item.nombre}</div>
            </div>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10,marginBottom:12}}>
              <div style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:10,padding:"12px 14px"}}>
                <div style={{fontSize:10,color:"#e4e9f6",textTransform:"uppercase",fontWeight:700,marginBottom:5}}>Precio venta</div>
                <div style={{fontSize:20,fontWeight:900,color:"#10b981"}}>EUR {(item.precioVenta||0).toFixed(2)}</div>
              </div>
              <div style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:10,padding:"12px 14px"}}>
                <div style={{fontSize:10,color:"#e4e9f6",textTransform:"uppercase",fontWeight:700,marginBottom:5}}>Stock actual</div>
                <div style={{fontSize:20,fontWeight:900,color:item.stock>0?"#a855f7":"#ef4444"}}>{item.stock||0} {item.unidad||"ud"}</div>
              </div>
              {item.categoria && (
                <div style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:10,padding:"12px 14px"}}>
                  <div style={{fontSize:10,color:"#e4e9f6",textTransform:"uppercase",fontWeight:700,marginBottom:5}}>Categoría</div>
                  <div style={{fontSize:14,fontWeight:700,color:"#e1e6f2"}}>{item.categoria}</div>
                </div>
              )}
              {item.ubicacion && (
                <div style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:10,padding:"12px 14px"}}>
                  <div style={{fontSize:10,color:"#e4e9f6",textTransform:"uppercase",fontWeight:700,marginBottom:5}}>Ubicación</div>
                  <div style={{fontSize:14,fontWeight:700,color:"#e1e6f2"}}>{item.ubicacion}</div>
                </div>
              )}
            </div>
            {item.descripcion && (
              <div style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:10,padding:"12px 14px",fontSize:13,color:"#e1e6f2",lineHeight:1.6}}>
                {item.descripcion}
              </div>
            )}
          </>
        )}
      </div>
      <div style={{color:"#3b4460",fontSize:10,marginTop:10}}>Europea de Maquinaria PMM SL</div>
    </div>
  );
};
const FichaPublicaMaquina = ({ codigo, data, cargando }) => {
  let found=null;
  (data?.clientes||[]).forEach(c=>(c.maquinas||[]).forEach(m=>{ if(m.codigo===codigo) found={m,cliente:c}; }));
  if(!found){
    // El código no apareció en ninguna ficha de cliente: puede ser una máquina
    // de Stock maquinaria nueva, todavía pendiente de venta (mismo espacio de
    // códigos MAQ-XXXX). El código se conserva al vender, así que la misma
    // etiqueta impresa seguirá siendo válida cuando la máquina pase al cliente.
    const stockItem = (data?.stock||[]).find(s=>s.codigo===codigo);
    if(stockItem) found = {m:stockItem, cliente:null, esStock:true};
  }
  const m=found?.m, cliente=found?.cliente, esStock=!!found?.esStock;
  const esPropia = !esStock && cliente?.id===0 && !m?.origenStock;
  const fotoPrincipal = m ? (m.foto || (m.fotos&&m.fotos[0]&&m.fotos[0].data) || null) : null;
  const avisosM = (m && cliente) ? (data.avisos||[]).filter(a=>parseInt(a.clienteId)===cliente.id && parseInt(a.maquinaId)===m.id) : [];
  const partesM = (m && cliente) ? (data.partes||[]).filter(p=>parseInt(p.clienteDirectoId)===cliente.id && parseInt(p.maquinaId)===m.id) : [];
  const historial = (m && cliente) ? [
    ...avisosM.map(a=>({tipo:"Aviso", fecha:a.fechaAviso, titulo:a.titulo, estado:a.estado})),
    ...partesM.map(p=>({tipo:"Parte", fecha:p.fecha, titulo:p.descripcion||p.numeroParte, estado:p.estado||""})),
  ].sort((a,b)=>new Date(b.fecha)-new Date(a.fecha)) : [];
  const [pdfMaquina,setPdfMaquina]=useState(null); // { url, nombre, blob } — vista previa del PDF de la máquina
  const cerrarPdfMaquina=()=>{ if(pdfMaquina) URL.revokeObjectURL(pdfMaquina.url); setPdfMaquina(null); };
  const compartirPdfMaquina=async()=>{
    if(!pdfMaquina) return;
    try{
      const archivo=new File([pdfMaquina.blob],pdfMaquina.nombre.replace(/[^\w\sñÑáéíóúÁÉÍÓÚ-]/g,"")+".pdf",{type:"application/pdf"});
      if(navigator.canShare&&navigator.canShare({files:[archivo]})){
        await navigator.share({files:[archivo],title:pdfMaquina.nombre});
      }else if(navigator.share){
        await navigator.share({title:pdfMaquina.nombre,url:pdfMaquina.url});
      }else{
        alert("Tu navegador no permite compartir directamente. Usa el botón Imprimir o descarga el PDF.");
      }
    }catch(e){ /* el usuario cerró el panel de compartir */ }
  };
  const generarPDFMaquina = () => {
    if(!m) return;
    const doc = new jsPDF({ orientation:"portrait", unit:"mm", format:"a4" });
    const W=210; const mg=18;
    const dibujarHeader = () => {
      doc.setFillColor(15,23,42); doc.rect(0,0,W,34,"F");
      doc.setFillColor(245,158,11); doc.rect(0,32,W,2.5,"F");
      try { doc.addImage(LOGO_CIRCULO, "JPEG", mg, 3, 26, 26); } catch(e) {}
      doc.setTextColor(255,255,255); doc.setFontSize(13); doc.setFont("helvetica","bold");
      doc.text("EUROPEA DE MAQUINARIA PMM SL",mg+30,12);
      doc.setFontSize(7); doc.setFont("helvetica","normal"); doc.setTextColor(190,200,220);
      doc.text("Carrer Mas del Jutge 33  ·  46900 Torrent (Valencia)  ·  CIF: B98527583",mg+30,18);
      doc.text("europeademaquinaria.com  ·  info@europeademaquinaria.com  ·  Tel: 961550707",mg+30,24);
      doc.setTextColor(245,158,11); doc.setFontSize(14); doc.setFont("helvetica","bold");
      doc.text(esStock?"FICHA DE STOCK":"FICHA DE MÁQUINA",W-mg,13,{align:"right"});
      doc.setTextColor(200,210,230); doc.setFontSize(8.5); doc.setFont("helvetica","normal");
      doc.text(m.codigo||"",W-mg,21,{align:"right"});
      doc.text("Fecha: "+fmtFecha(today()),W-mg,27,{align:"right"});
      doc.setFillColor(255,255,255); doc.rect(0,34,W,264,"F");
    };
    dibujarHeader();
    let y=42;
    const box=(titulo,filas,yStart)=>{
      doc.setFillColor(230,235,245); doc.roundedRect(mg,yStart,W-mg*2,7,1,1,"F");
      doc.setDrawColor(180,190,210); doc.roundedRect(mg,yStart,W-mg*2,7,1,1,"S");
      doc.setDrawColor(255,255,255);
      doc.setTextColor(40,60,110); doc.setFontSize(8); doc.setFont("helvetica","bold");
      doc.text(titulo.toUpperCase(),mg+4,yStart+5);
      let fy=yStart+13;
      filas.forEach(([l,v])=>{
        if(!v&&v!==0) return;
        doc.setTextColor(100,115,145); doc.setFontSize(7.5); doc.setFont("helvetica","normal");
        doc.text(l+":",mg+4,fy);
        doc.setTextColor(25,35,60); doc.setFontSize(9); doc.setFont("helvetica","bold");
        const lines=doc.splitTextToSize(String(v),W-mg*2-52);
        doc.text(lines,mg+52,fy);
        fy+=Math.max(lines.length*5.5,6.5);
      });
      return fy+4;
    };
    const asegurarEspacio = (necesario) => {
      if (y+necesario > 268) { doc.addPage(); dibujarHeader(); y=42; }
    };
    const tablaSeccion = (titulo, columnas, filas) => {
      asegurarEspacio(20);
      doc.setFillColor(230,235,245); doc.roundedRect(mg,y,W-mg*2,7,1,1,"F");
      doc.setDrawColor(180,190,210); doc.roundedRect(mg,y,W-mg*2,7,1,1,"S");
      doc.setDrawColor(255,255,255);
      doc.setTextColor(40,60,110); doc.setFontSize(8); doc.setFont("helvetica","bold");
      doc.text(titulo.toUpperCase(),mg+4,y+5); y+=11;
      doc.setFillColor(40,60,110); doc.rect(mg,y,W-mg*2,6,"F");
      let cx=mg;
      doc.setTextColor(255,255,255); doc.setFontSize(7.5); doc.setFont("helvetica","bold");
      columnas.forEach(col=>{ doc.text(col.label,cx+(col.align==="right"?col.w-3:3),y+4.5,{align:col.align==="right"?"right":"left"}); cx+=col.w; });
      y+=7;
      filas.forEach((fila,j)=>{
        asegurarEspacio(8);
        const bgClr = j%2===0 ? [248,250,255] : [255,255,255];
        doc.setFillColor(...bgClr); doc.rect(mg,y-1,W-mg*2,7,"F");
        doc.setTextColor(25,35,70); doc.setFontSize(8.5); doc.setFont("helvetica","normal");
        let cx2=mg;
        columnas.forEach((col,k)=>{
          doc.text(String(fila[k]??"—"),cx2+(col.align==="right"?col.w-3:3),y+4,{align:col.align==="right"?"right":"left"});
          cx2+=col.w;
        });
        y+=7;
      });
      y+=5;
    };
    if(fotoPrincipal){
      try {
        const fotoW=60, fotoH=45;
        doc.addImage(fotoPrincipal,mg,y,fotoW,fotoH);
        doc.setDrawColor(200,205,220); doc.roundedRect(mg,y,fotoW,fotoH,1,1,"S");
        y+=fotoH+6;
      } catch(e) {}
    }
    if(esStock){
      const tar=(m.codigos||[]).reduce((s,c)=>s+(parseNum(c.valor)||0),0);
      const ven=parseNum(m.precioVentaObj)||0;
      y=box("Datos de la máquina",[
        ["Código",m.codigo||"—"],
        ["Marca",m.marca||"—"],
        ["Modelo",m.modelo||"—"],
        ["Matrícula / Nº serie",m.matricula||"—"],
        ["Año",m.anyo||"—"],
        ["Estado",m.estado||"—"],
      ],y);
      asegurarEspacio(20);
      y=box("Valoración",[
        ["Precio de tarifa","€"+tar.toLocaleString()],
        ["Precio estimado",ven>0?"€"+ven.toLocaleString():"—"],
      ],y);
      if(m.notas?.trim()){
        asegurarEspacio(20);
        y=box("Notas",[["Notas",m.notas]],y);
      }
      if((m.codigos||[]).length>0){
        y+=2;
        tablaSeccion("Códigos de configuración ("+m.codigos.length+")",
          [{label:"CÓDIGO",w:40},{label:"DESCRIPCIÓN",w:124},{label:"VALOR",w:30,align:"right"}],
          m.codigos.map(c=>[c.codigo||"—",c.descripcion||"—","€"+(parseFloat(c.valor)||0).toLocaleString()])
        );
      }
    } else {
      y=box("Datos de la máquina",[
        ["Código",m.codigo||"—"],
        ["Nombre",m.nombre||"—"],
        ["Marca",m.marca||"—"],
        ["Modelo",m.modelo||"—"],
        ["Nº serie / matrícula",m.serie||"—"],
        ["Año",m.anyo||"—"],
      ],y);
      asegurarEspacio(20);
      y=box("Cliente",[
        ["Empresa",cliente.nombreEmpresa||"—"],
        ["CIF / DNI",cliente.cif||"—"],
        ["Localidad",cliente.localidad||"—"],
      ],y);
      if(esPropia && m.precioVenta){
        asegurarEspacio(20);
        y=box("Valoración",[["Precio de venta","€"+parseNum(m.precioVenta).toLocaleString("es-ES")]],y);
      }
      if(m.notas?.trim()){
        asegurarEspacio(20);
        y=box("Notas",[["Notas",m.notas]],y);
      }
      if(historial.length>0){
        y+=2;
        tablaSeccion("Historial de intervenciones ("+historial.length+")",
          [{label:"FECHA",w:26},{label:"TIPO",w:24},{label:"DESCRIPCIÓN",w:94},{label:"ESTADO",w:30}],
          historial.map(h=>[h.fecha?fmtFecha(h.fecha):"—",h.tipo,h.titulo||"—",h.estado||"—"])
        );
      }
    }
    const totalPaginas = doc.getNumberOfPages();
    for(let pg=1; pg<=totalPaginas; pg++){
      doc.setPage(pg);
      doc.setFillColor(245,158,11); doc.rect(0,281,W,1.5,"F");
      doc.setFillColor(15,23,42); doc.rect(0,282.5,W,14.5,"F");
      doc.setTextColor(190,200,220); doc.setFontSize(7); doc.setFont("helvetica","normal");
      doc.text("Europea de Maquinaria PMM SL  ·  CIF B98527583  ·  europeademaquinaria.com",W/2,291,{align:"center"});
      if(totalPaginas>1){ doc.setTextColor(190,200,220); doc.text("Página "+pg+"/"+totalPaginas,W-mg,291,{align:"right"}); }
    }
    try {
      const dataUri = doc.output("datauristring");
      const byteString = atob(dataUri.split(",")[1]);
      const bytes = new Uint8Array(byteString.length);
      for (let i=0;i<byteString.length;i++) bytes[i]=byteString.charCodeAt(i);
      const blob = new Blob([bytes], {type:"application/pdf"});
      if(pdfMaquina) URL.revokeObjectURL(pdfMaquina.url);
      const url = URL.createObjectURL(blob);
      setPdfMaquina({ url, nombre: "Máquina "+(m.codigo||""), blob });
    } catch(e) { alert("No se pudo generar el PDF de la máquina."); }
  };
  const cerrarFicha = () => { try{ window.location.href = window.location.origin + window.location.pathname; }catch(e){ window.location.search=""; } };
  return (
    <div style={{minHeight:"100vh",background:"#0d1117",color:"#f1f3f9",fontFamily:"Arial,sans-serif",display:"flex",flexDirection:"column",alignItems:"center",padding:"0 0 30px"}}>
      <div style={{width:"100%",background:"#151b2a",borderBottom:"2px solid #0ea5e933",padding:"calc(16px + env(safe-area-inset-top, 0px)) 16px 16px",textAlign:"center",position:"relative"}}>
        <button onClick={cerrarFicha} aria-label="Cerrar" style={{position:"absolute",top:"calc(10px + env(safe-area-inset-top, 0px))",right:12,background:"#2a3550",border:"none",borderRadius:8,padding:7,color:"#f1f3f9",cursor:"pointer",display:"flex"}}><Icon name="close" size={16}/></button>
        <div style={{fontSize:10,color:"#0ea5e9",letterSpacing:2,textTransform:"uppercase",fontWeight:700,marginBottom:6}}>Europea de Maquinaria PMM SL</div>
        <div style={{fontSize:13,color:"#e4e9f6"}}>Ficha de máquina</div>
        {m && (
          <button onClick={generarPDFMaquina} style={{marginTop:10,background:"#0ea5e9",color:"#fff",border:"none",borderRadius:8,padding:"8px 14px",fontWeight:700,fontSize:12,cursor:"pointer",display:"inline-flex",alignItems:"center",gap:6}}>
            <Icon name="print" size={13}/>Generar PDF
          </button>
        )}
      </div>
      <div style={{width:"100%",maxWidth:420,padding:"20px 16px"}}>
        {!m ? (
          <div style={{textAlign:"center",color:"#e4e9f6",padding:"40px 10px"}}>
            {cargando ? "Cargando máquina..." : (
              <>
                <div style={{fontSize:36,marginBottom:10}}>❓</div>
                <div style={{fontWeight:700,color:"#f1f3f9",marginBottom:4}}>Máquina no encontrada</div>
                <div style={{fontSize:13}}>No existe ninguna máquina con el código "{codigo}".</div>
              </>
            )}
          </div>
        ) : (
          <>
            {fotoPrincipal && <img src={fotoPrincipal} alt={m.nombre||m.modelo} style={{width:"100%",maxHeight:220,objectFit:"cover",borderRadius:12,border:"1px solid #2a3550",marginBottom:14}}/>}
            <div style={{textAlign:"center",marginBottom:16}}>
              <div style={{fontSize:22,fontWeight:900,letterSpacing:2,color:"#0ea5e9",fontFamily:"monospace"}}>{m.codigo}</div>
              <div style={{fontSize:16,fontWeight:700,marginTop:4}}>{m.nombre||`${m.marca||""} ${m.modelo||""}`}</div>
              {esStock ? (
                <div style={{fontSize:12,color:"#e4e9f6",marginTop:2}}>Stock maquinaria nueva · {m.vendida?"vendida":"pendiente de venta"}</div>
              ) : (
                <div style={{fontSize:12,color:"#e4e9f6",marginTop:2}}>Cliente: {cliente.nombreEmpresa}</div>
              )}
            </div>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10,marginBottom:12}}>
              <div style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:10,padding:"12px 14px"}}>
                <div style={{fontSize:10,color:"#e4e9f6",textTransform:"uppercase",fontWeight:700,marginBottom:5}}>Matrícula / Serie</div>
                <div style={{fontSize:16,fontWeight:800}}>{m.serie||m.matricula||"—"}</div>
              </div>
              <div style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:10,padding:"12px 14px"}}>
                <div style={{fontSize:10,color:"#e4e9f6",textTransform:"uppercase",fontWeight:700,marginBottom:5}}>Año</div>
                <div style={{fontSize:16,fontWeight:800}}>{m.anyo||"—"}</div>
              </div>
              <div style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:10,padding:"12px 14px"}}>
                <div style={{fontSize:10,color:"#e4e9f6",textTransform:"uppercase",fontWeight:700,marginBottom:5}}>Marca</div>
                <div style={{fontSize:14,fontWeight:700,color:"#e1e6f2"}}>{m.marca||"—"}</div>
              </div>
              <div style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:10,padding:"12px 14px"}}>
                <div style={{fontSize:10,color:"#e4e9f6",textTransform:"uppercase",fontWeight:700,marginBottom:5}}>Modelo</div>
                <div style={{fontSize:14,fontWeight:700,color:"#e1e6f2"}}>{m.modelo||"—"}</div>
              </div>
              {esStock && (()=>{ const tar=(m.codigos||[]).reduce((s,c)=>s+(parseNum(c.valor)||0),0); const ven=parseNum(m.precioVentaObj)||0; return (<>
                <div style={{background:"#151b2a",border:"1px solid #3b82f633",borderRadius:10,padding:"12px 14px"}}>
                  <div style={{fontSize:10,color:"#e4e9f6",textTransform:"uppercase",fontWeight:700,marginBottom:5}}>Precio de tarifa</div>
                  <div style={{fontSize:16,fontWeight:800,color:"#3b82f6"}}>€{tar.toLocaleString("es-ES")}</div>
                </div>
                <div style={{background:"#151b2a",border:"1px solid #10b98133",borderRadius:10,padding:"12px 14px"}}>
                  <div style={{fontSize:10,color:"#e4e9f6",textTransform:"uppercase",fontWeight:700,marginBottom:5}}>Precio estimado</div>
                  <div style={{fontSize:16,fontWeight:800,color:"#10b981"}}>{ven>0?"€"+ven.toLocaleString():"—"}</div>
                </div>
              </>); })()}
              {esPropia && m.precioVenta && (
                <div style={{background:"#151b2a",border:"1px solid #10b98133",borderRadius:10,padding:"12px 14px",gridColumn:"1/-1"}}>
                  <div style={{fontSize:10,color:"#e4e9f6",textTransform:"uppercase",fontWeight:700,marginBottom:5}}>Precio de venta</div>
                  <div style={{fontSize:16,fontWeight:800,color:"#10b981"}}>€{parseNum(m.precioVenta).toLocaleString("es-ES")}</div>
                </div>
              )}
            </div>
            {m.notas && <div style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:10,padding:"12px 14px",fontSize:13,color:"#e1e6f2",lineHeight:1.6,marginBottom:12}}>{m.notas}</div>}
            {esStock ? (
              <>
                <div style={{fontSize:11,fontWeight:700,color:"#e4e9f6",textTransform:"uppercase",letterSpacing:".7px",marginBottom:8}}>Códigos de configuración ({(m.codigos||[]).length})</div>
                <div style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:10,overflow:"hidden"}}>
                  {(m.codigos||[]).length===0 && <div style={{padding:"18px",textAlign:"center",color:"#e4e9f6",fontSize:12}}>Sin códigos registrados</div>}
                  {(m.codigos||[]).map((c,i)=>(
                    <div key={c.id||i} style={{display:"flex",alignItems:"center",gap:8,padding:"10px 14px",borderTop:i?"1px solid #1a2236":"none"}}>
                      <div style={{flex:1,minWidth:0}}>
                        <div style={{color:"#f1f3f9",fontSize:12,fontWeight:600,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{c.codigo||"—"}</div>
                        <div style={{color:"#e4e9f6",fontSize:10}}>{c.descripcion||"—"}</div>
                      </div>
                      <div style={{color:"#3b82f6",fontWeight:800,fontSize:12}}>€{(parseFloat(c.valor)||0).toLocaleString()}</div>
                    </div>
                  ))}
                </div>
              </>
            ) : (
              <>
                <div style={{fontSize:11,fontWeight:700,color:"#e4e9f6",textTransform:"uppercase",letterSpacing:".7px",marginBottom:8}}>Historial de intervenciones ({historial.length})</div>
                <div style={{background:"#151b2a",border:"1px solid #2a3550",borderRadius:10,overflow:"hidden"}}>
                  {historial.length===0 && <div style={{padding:"18px",textAlign:"center",color:"#e4e9f6",fontSize:12}}>Sin avisos ni partes registrados</div>}
                  {historial.map((h,i)=>(
                    <div key={i} style={{display:"flex",alignItems:"center",gap:8,padding:"10px 14px",borderTop:i?"1px solid #1a2236":"none"}}>
                      <span style={{background:h.tipo==="Aviso"?"#f59e0b20":"#3b82f620",color:h.tipo==="Aviso"?"#f59e0b":"#3b82f6",border:"1px solid "+(h.tipo==="Aviso"?"#f59e0b44":"#3b82f644"),borderRadius:6,padding:"2px 7px",fontSize:9,fontWeight:800}}>{h.tipo}</span>
                      <div style={{flex:1,minWidth:0}}>
                        <div style={{color:"#f1f3f9",fontSize:12,fontWeight:600,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{h.titulo||"—"}</div>
                        <div style={{color:"#e4e9f6",fontSize:10}}>{h.fecha} {h.estado&&("· "+h.estado)}</div>
                      </div>
                    </div>
                  ))}
                </div>
              </>
            )}
          </>
        )}
      </div>
      <div style={{color:"#3b4460",fontSize:10,marginTop:10}}>Europea de Maquinaria PMM SL</div>
      {pdfMaquina && (()=>{ const esMobil = window.innerWidth<=820; return (
        <div style={{position:"fixed",top:0,left:0,right:0,bottom:0,background:"rgba(0,0,0,.75)",zIndex:1200,display:"flex",flexDirection:"column"}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"12px 16px",paddingTop:"calc(12px + env(safe-area-inset-top, 0px))",background:"#151b2a",borderBottom:"1px solid #2a3550",flexShrink:0,gap:8,flexWrap:"wrap"}}>
            <span style={{color:"#f1f3f9",fontWeight:700,fontSize:14,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",minWidth:0,flex:"1 1 120px"}}>{pdfMaquina.nombre} (vista previa)</span>
            <div style={{display:"flex",gap:8,flexShrink:0}}>
              <button onClick={()=>{ if(esMobil){ window.open(pdfMaquina.url,"_blank"); return; } const ifr=document.getElementById("pdfMaquinaFrame"); try{ ifr.contentWindow.focus(); ifr.contentWindow.print(); }catch(e){} }} style={{background:"#0ea5e9",color:"#fff",border:"none",borderRadius:8,padding:"8px 12px",fontWeight:700,fontSize:13,cursor:"pointer",display:"flex",alignItems:"center",gap:6}}>
                <Icon name="print" size={14}/>Imprimir
              </button>
              <button onClick={compartirPdfMaquina} style={{background:"#10b981",color:"#fff",border:"none",borderRadius:8,padding:"8px 12px",fontWeight:700,fontSize:13,cursor:"pointer",display:"flex",alignItems:"center",gap:6}}>
                <Icon name="share" size={14}/>Compartir
              </button>
              <button onClick={cerrarPdfMaquina} style={{background:"#2a3550",border:"none",borderRadius:8,padding:"8px 10px",color:"#f1f3f9",cursor:"pointer",display:"flex",alignItems:"center"}}>
                <Icon name="close" size={16}/>
              </button>
            </div>
          </div>
          {esMobil ? (
            <div style={{flex:1,width:"100%",background:"#fff",display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",gap:14,padding:24,textAlign:"center"}}>
              <div style={{fontSize:40}}>📄</div>
              <div style={{color:"#333",fontSize:14,maxWidth:280}}>La vista previa no se ajusta bien en móvil. Ábrelo a pantalla completa:</div>
              <button onClick={()=>window.open(pdfMaquina.url,"_blank")} style={{background:"#0ea5e9",color:"#fff",border:"none",borderRadius:8,padding:"10px 18px",fontWeight:700,fontSize:14,cursor:"pointer"}}>Abrir PDF</button>
            </div>
          ) : (
            <iframe id="pdfMaquinaFrame" src={pdfMaquina.url+"#view=FitH"} title="Vista previa de la ficha de la máquina" style={{flex:1,width:"100%",border:"none",background:"#fff"}}/>
          )}
        </div>
      );})()}
    </div>
  );
};

// ── ErrorBoundary: muestra el error en vez de pantalla negra ─────────────────
class AppErrorBoundary extends React.Component {
  constructor(props) { super(props); this.state = { error: null }; }
  static getDerivedStateFromError(e) { return { error: e }; }
  componentDidCatch(e, info) { console.error("App crash:", e, info); }
  render() {
    if (!this.state.error) return this.props.children;
    return (
      <div style={{minHeight:"100vh",display:"flex",alignItems:"center",justifyContent:"center",background:"#0d1117",padding:20}}>
        <div style={{background:"#151b2a",border:"1px solid #dc2626",borderRadius:16,padding:"28px 32px",maxWidth:480,width:"100%"}}>
          <div style={{color:"#dc2626",fontWeight:900,fontSize:18,marginBottom:10}}>⚠ Error al cargar la aplicación</div>
          <div style={{color:"#e4e9f6",fontSize:13,marginBottom:16}}>{String(this.state.error)}</div>
          <div style={{display:"flex",gap:10,flexWrap:"wrap"}}>
            <button onClick={()=>window.location.replace("/?reset")} style={{background:"#dc2626",color:"#fff",border:"none",borderRadius:8,padding:"9px 18px",fontWeight:700,cursor:"pointer",fontSize:13}}>Limpiar caché y reiniciar</button>
            <button onClick={()=>window.location.reload()} style={{background:"#2a3550",color:"#e4e9f6",border:"none",borderRadius:8,padding:"9px 18px",fontWeight:700,cursor:"pointer",fontSize:13}}>Recargar</button>
          </div>
        </div>
      </div>
    );
  }
}

// ─── Página pública de aceptación de presupuesto ────────────────────────────
function AceptarPresupuestoPublico({ token }) {
  const [estado, setEstado] = useState("cargando"); // cargando|ok|error|ya_aceptado|enviando|exito
  const [prs, setPrs] = useState(null);
  const [nombre, setNombre] = useState("");
  const [acepto, setAcepto] = useState(false);
  const [showPayNotice, setShowPayNotice] = useState(false);
  const [noticeAcept, setNoticeAcept] = useState(false);
  const [errMsg, setErrMsg] = useState("");

  const fmt = n => new Intl.NumberFormat("es-ES",{style:"currency",currency:"EUR"}).format(n||0);

  useEffect(()=>{
    fetch(`/api/aceptar-presupuesto.php?token=${encodeURIComponent(token)}`)
      .then(r=>r.json())
      .then(d=>{
        if(d.error==="not_found"){setEstado("error");setErrMsg("Presupuesto no encontrado. Puede que el enlace haya caducado.");return;}
        if(d.error){setEstado("error");setErrMsg("Error al cargar el presupuesto.");return;}
        setPrs(d);
        if(d.yaAceptado){setEstado("ya_aceptado");return;}
        setEstado("ok");
        // Mostrar aviso de pago anticipado automáticamente
        if(d.formaPago==="Pago anticipado") setShowPayNotice(true);
      })
      .catch(()=>{setEstado("error");setErrMsg("No se pudo conectar con el servidor.");});
  },[token]);

  const enviarAceptacion = async () => {
    if(!nombre.trim()){alert("Por favor, introduce tu nombre completo.");return;}
    if(!acepto){alert("Debes marcar la casilla de aceptación.");return;}
    if(prs?.formaPago==="Pago anticipado"&&!noticeAcept){setShowPayNotice(true);return;}
    setEstado("enviando");
    try {
      const r = await fetch("/api/aceptar-presupuesto.php",{
        method:"POST", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({token, nombre: nombre.trim()}),
      });
      const d = await r.json();
      if(d.ok) setEstado("exito");
      else if(d.error==="ya_aceptado") setEstado("ya_aceptado");
      else {setEstado("ok");setErrMsg("Error al enviar: "+(d.error||"desconocido"));}
    } catch(e) {setEstado("ok");setErrMsg("Error de red al enviar.");}
  };

  const base = {fontFamily:"'DM Sans','Segoe UI',Arial,sans-serif",minHeight:"100vh",background:"#f1f5f9",color:"#1a1a1a"};
  const card = {background:"#fff",borderRadius:16,boxShadow:"0 4px 32px rgba(0,0,0,.10)",padding:"32px 28px",maxWidth:640,margin:"0 auto"};
  const emp = prs?.empresa;

  return (
    <div style={base}>
      {/* Cabecera */}
      <div style={{background:"#0a0f1a",padding:"16px 24px",display:"flex",alignItems:"center",gap:12}}>
        <img src={LOGO_URL} style={{width:36,height:36,borderRadius:8,objectFit:"contain"}} alt="EM"/>
        <div>
          <div style={{color:"#f1f3f9",fontWeight:800,fontSize:14}}>{emp?.razonSocial||"Europea de Maquinaria PMM SL"}</div>
          {emp?.nif&&<div style={{color:"#94a3b8",fontSize:11}}>NIF: {emp.nif}</div>}
        </div>
      </div>

      <div style={{padding:"28px 16px"}}>
        {/* Modal aviso pago anticipado */}
        {showPayNotice&&<div style={{position:"fixed",top:0,left:0,right:0,bottom:0,background:"rgba(0,0,0,.6)",zIndex:1000,display:"flex",alignItems:"center",justifyContent:"center",padding:16}}>
          <div style={{background:"#fff",borderRadius:14,padding:"28px 24px",maxWidth:440,width:"100%",boxShadow:"0 24px 60px rgba(0,0,0,.3)"}}>
            <div style={{fontSize:32,marginBottom:10,textAlign:"center"}}>⚠️</div>
            <h3 style={{margin:"0 0 12px",fontSize:18,color:"#92400e",textAlign:"center"}}>Pago anticipado requerido</h3>
            <p style={{color:"#78350f",fontSize:14,margin:"0 0 16px",lineHeight:1.6}}>
              Este presupuesto tiene como forma de pago <strong>Pago anticipado</strong>.<br/>
              El importe de <strong style={{fontSize:16}}>{fmt(prs?.total)}</strong> deberá abonarse antes de que iniciemos el trabajo.
            </p>
            {(prs?.empresa?.cuentasBancarias||[]).length>0&&<div style={{background:"#fef3c7",borderRadius:8,padding:"10px 14px",marginBottom:16}}>
              <div style={{fontSize:12,color:"#92400e",marginBottom:8,fontWeight:700}}>Datos bancarios para el pago:</div>
              {(prs.empresa.cuentasBancarias).map((c,i)=><div key={i} style={{marginBottom:i<prs.empresa.cuentasBancarias.length-1?8:0}}><div style={{fontWeight:700,fontSize:13,color:"#78350f"}}>{c.banco}</div><div style={{fontFamily:"monospace",fontWeight:700,fontSize:14,letterSpacing:1,color:"#92400e"}}>{c.iban}</div></div>)}
            </div>}
            <p style={{color:"#64748b",fontSize:12,margin:"0 0 18px"}}>Al aceptar el presupuesto confirmas que estás informado/a de esta condición.</p>
            <div style={{display:"flex",gap:10}}>
              <button onClick={()=>{setNoticeAcept(true);setShowPayNotice(false);}} style={{flex:1,background:"#d97706",border:"none",borderRadius:8,padding:"11px",color:"#fff",fontWeight:700,fontSize:14,cursor:"pointer"}}>Entendido, acepto</button>
              <button onClick={()=>setShowPayNotice(false)} style={{flex:1,background:"#f1f5f9",border:"1px solid #cbd5e1",borderRadius:8,padding:"11px",color:"#475569",fontWeight:600,fontSize:14,cursor:"pointer"}}>Cancelar</button>
            </div>
          </div>
        </div>}

        {/* Cargando */}
        {estado==="cargando"&&<div style={{...card,textAlign:"center",padding:48}}><div style={{fontSize:32,marginBottom:12}}>⏳</div><p style={{color:"#64748b"}}>Cargando presupuesto...</p></div>}

        {/* Error */}
        {estado==="error"&&<div style={{...card,textAlign:"center",padding:48}}><div style={{fontSize:32,marginBottom:12}}>❌</div><h3 style={{margin:"0 0 8px"}}>Enlace no válido</h3><p style={{color:"#64748b",fontSize:14}}>{errMsg}</p><p style={{color:"#94a3b8",fontSize:12,marginTop:16}}>Si crees que es un error, contacta con nosotros.</p></div>}

        {/* Ya aceptado */}
        {estado==="ya_aceptado"&&<div style={{...card,textAlign:"center",padding:48}}><div style={{fontSize:40,marginBottom:12}}>✅</div><h3 style={{margin:"0 0 8px",color:"#16a34a"}}>Presupuesto ya aceptado</h3>{prs?.aceptadoPor&&<p style={{color:"#64748b",fontSize:14}}>Aceptado por <strong>{prs.aceptadoPor}</strong>{prs?.aceptadoEn?` el ${new Date(prs.aceptadoEn).toLocaleString("es-ES")}`:""}</p>}<p style={{color:"#94a3b8",fontSize:12,marginTop:16}}>En breve nos pondremos en contacto contigo.</p></div>}

        {/* Éxito */}
        {estado==="exito"&&<div style={{...card,textAlign:"center",padding:"40px 48px"}}><div style={{marginBottom:16}}><img src="https://gestion-europea.com/logo-circulo.jpg" alt="Europea de Maquinaria" style={{width:84,height:84,borderRadius:"50%",objectFit:"cover",boxShadow:"0 2px 12px rgba(0,0,0,0.12)"}}/></div><h2 style={{margin:"0 0 4px",fontSize:20,fontWeight:700,color:"#1e293b",letterSpacing:"-0.3px"}}>Europea de Maquinaria PMM SL</h2><p style={{margin:"0 0 20px",color:"#16a34a",fontSize:16,fontWeight:600}}>✅ Presupuesto aceptado</p><p style={{color:"#475569",fontSize:15,marginBottom:8}}>Hemos recibido tu aceptación del presupuesto <strong>{prs?.numero}</strong>.</p><p style={{color:"#64748b",fontSize:14}}>Nos pondremos en contacto contigo a la mayor brevedad para coordinar los siguientes pasos.</p>{prs?.formaPago==="Pago anticipado"&&<div style={{background:"#fef3c7",borderRadius:10,padding:"14px 18px",marginTop:20,textAlign:"left"}}><p style={{margin:"0 0 6px",color:"#92400e",fontSize:13,fontWeight:600}}>⚠️ Recuerda que el pago es anticipado</p><p style={{margin:"0 0 8px",color:"#78350f",fontSize:13}}>Importe: <strong>{fmt(prs?.total)}</strong></p>{(prs?.empresa?.cuentasBancarias||[]).map((c,i)=><div key={i} style={{marginBottom:4}}><span style={{color:"#78350f",fontWeight:600,fontSize:12}}>{c.banco}: </span><span style={{fontFamily:"monospace",fontSize:12,color:"#92400e",fontWeight:700}}>{c.iban}</span></div>)}</div>}<div style={{borderTop:"1px solid #e2e8f0",marginTop:28,paddingTop:20,textAlign:"center"}}><p style={{margin:"0 0 6px",fontSize:13,fontWeight:600,color:"#334155"}}>Europea de Maquinaria PMM SL</p>{prs?.empresa?.dirFiscal&&<p style={{margin:"0 0 2px",color:"#64748b",fontSize:12}}>{prs.empresa.dirFiscal}{prs.empresa.cpFiscal?`, ${prs.empresa.cpFiscal}`:""}{prs.empresa.localidad?` ${prs.empresa.localidad}`:""}</p>}<div style={{display:"flex",justifyContent:"center",gap:20,marginTop:6,flexWrap:"wrap"}}>{prs?.empresa?.telefono&&<a href={`tel:${prs.empresa.telefono}`} style={{color:"#475569",fontSize:12,textDecoration:"none"}}>📞 {prs.empresa.telefono}</a>}{prs?.empresa?.email&&<a href={`mailto:${prs.empresa.email}`} style={{color:"#475569",fontSize:12,textDecoration:"none"}}>✉️ {prs.empresa.email}</a>}{prs?.empresa?.web&&<a href={`https://${prs.empresa.web}`} target="_blank" rel="noreferrer" style={{color:"#475569",fontSize:12,textDecoration:"none"}}>🌐 {prs.empresa.web}</a>}</div><p style={{color:"#94a3b8",fontSize:11,marginTop:14}}>Puedes cerrar esta página.</p></div></div>}

        {/* Formulario */}
        {(estado==="ok"||estado==="enviando")&&prs&&(
          <div style={card}>
            <h2 style={{margin:"0 0 4px",fontSize:20}}>Presupuesto {prs.numero}</h2>
            <p style={{color:"#64748b",fontSize:13,margin:"0 0 20px"}}>
              {prs.fecha&&`Fecha: ${new Date(prs.fecha).toLocaleDateString("es-ES")}`}
              {prs.validezHasta&&` · Válido hasta: ${new Date(prs.validezHasta).toLocaleDateString("es-ES")}`}
            </p>

            {/* Líneas */}
            <div style={{overflowX:"auto",marginBottom:16}}>
              <table style={{width:"100%",borderCollapse:"collapse",fontSize:13}}>
                <thead><tr style={{background:"#f8fafc"}}>
                  {["Descripción","Cant.","P. Unit.","Subtotal"].map(h=><th key={h} style={{padding:"8px 10px",textAlign:h==="Descripción"?"left":"right",color:"#64748b",fontWeight:600,borderBottom:"2px solid #e2e8f0",whiteSpace:"nowrap"}}>{h}</th>)}
                </tr></thead>
                <tbody>
                  {(prs.lineas||[]).filter(l=>l.descripcion?.trim()).map((l,i)=>(
                    <tr key={i} style={{borderBottom:"1px solid #f1f5f9"}}>
                      <td style={{padding:"9px 10px"}}>{l.descripcion}</td>
                      <td style={{padding:"9px 10px",textAlign:"right"}}>{l.cantidad}</td>
                      <td style={{padding:"9px 10px",textAlign:"right"}}>{fmt(l.precioNeto||l.precioUnitario)}</td>
                      <td style={{padding:"9px 10px",textAlign:"right",fontWeight:600}}>{fmt(l.subtotal)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* Totales */}
            <div style={{background:"#f8fafc",borderRadius:8,padding:"12px 16px",marginBottom:16,textAlign:"right"}}>
              <div style={{color:"#64748b",fontSize:13}}>Base imponible: <strong style={{color:"#1a1a1a"}}>{fmt(prs.baseImponible)}</strong></div>
              <div style={{color:"#64748b",fontSize:13}}>IVA ({prs.tipoIVA}%): <strong style={{color:"#1a1a1a"}}>{fmt(prs.cuotaIVA)}</strong></div>
              <div style={{color:"#16a34a",fontSize:18,fontWeight:800,marginTop:4}}>Total: {fmt(prs.total)}</div>
            </div>

            {/* Forma de pago */}
            {prs.formaPago&&<div style={{background:prs.formaPago==="Pago anticipado"?"#fef3c7":"#f0fdf4",borderRadius:8,padding:"10px 14px",marginBottom:16,display:"flex",alignItems:"center",gap:8}}>
              <span style={{fontSize:18}}>{prs.formaPago==="Pago anticipado"?"⚠️":"💳"}</span>
              <div>
                <span style={{fontWeight:700,fontSize:13,color:prs.formaPago==="Pago anticipado"?"#92400e":"#166534"}}>Forma de pago: {prs.formaPago}</span>
                {prs.formaPago==="Pago anticipado"&&<div style={{fontSize:12,color:"#78350f",marginTop:2}}>El trabajo se iniciará una vez confirmado el pago.</div>}
              </div>
            </div>}

            {/* Notas */}
            {prs.notas&&<div style={{background:"#f8fafc",borderRadius:8,padding:"10px 14px",marginBottom:16,fontSize:13,color:"#475569"}}><strong>Notas:</strong> {prs.notas}</div>}

            {/* Formulario de aceptación */}
            <div style={{borderTop:"2px solid #e2e8f0",paddingTop:20,marginTop:8}}>
              <h3 style={{margin:"0 0 14px",fontSize:16}}>Firma y aceptación</h3>
              <div style={{marginBottom:12}}>
                <label style={{display:"block",fontSize:13,fontWeight:600,color:"#374151",marginBottom:5}}>Nombre completo del firmante *</label>
                <input value={nombre} onChange={e=>setNombre(e.target.value)} placeholder="Nombre y apellidos" style={{width:"100%",boxSizing:"border-box",border:"1px solid #cbd5e1",borderRadius:8,padding:"10px 12px",fontSize:14,outline:"none",fontFamily:"inherit"}}/>
              </div>
              <label style={{display:"flex",gap:10,alignItems:"flex-start",cursor:"pointer",marginBottom:18,padding:"12px 14px",background:acepto?"#f0fdf4":"#f8fafc",borderRadius:8,border:`1px solid ${acepto?"#86efac":"#e2e8f0"}`}}>
                <input type="checkbox" checked={acepto} onChange={e=>setAcepto(e.target.checked)} style={{marginTop:2,accentColor:"#16a34a",width:16,height:16,flexShrink:0}}/>
                <span style={{fontSize:13,color:"#374151",lineHeight:1.5}}>
                  He leído y acepto el presupuesto <strong>{prs.numero}</strong> por importe de <strong>{fmt(prs.total)}</strong>{prs.formaPago?` con forma de pago "${prs.formaPago}"`:""}.
                  {prs.formaPago==="Pago anticipado"&&<span style={{color:"#92400e"}}> Entiendo que el pago debe realizarse antes del inicio del trabajo.</span>}
                </span>
              </label>
              {errMsg&&<div style={{background:"#fef2f2",border:"1px solid #fca5a5",borderRadius:8,padding:"8px 12px",marginBottom:12,color:"#dc2626",fontSize:13}}>{errMsg}</div>}
              <button onClick={enviarAceptacion} disabled={estado==="enviando"||!nombre.trim()||!acepto}
                style={{width:"100%",background:(estado==="enviando"||!nombre.trim()||!acepto)?"#94a3b8":"#16a34a",border:"none",borderRadius:10,padding:"14px",color:"#fff",fontWeight:800,fontSize:16,cursor:(estado==="enviando"||!nombre.trim()||!acepto)?"not-allowed":"pointer",transition:"background .15s"}}>
                {estado==="enviando"?"Enviando...":"✅ Firmar y aceptar presupuesto"}
              </button>
              <p style={{textAlign:"center",color:"#94a3b8",fontSize:11,marginTop:10}}>
                Tu aceptación quedará registrada con fecha, hora e IP como firma electrónica válida.
              </p>
            </div>
          </div>
        )}

        {/* Pie */}
        <div style={{textAlign:"center",marginTop:24,color:"#94a3b8",fontSize:11}}>
          {emp?.razonSocial} {emp?.nif&&`· NIF: ${emp.nif}`}
          {emp?.email&&<> · <a href={`mailto:${emp.email}`} style={{color:"#94a3b8"}}>{emp.email}</a></>}
        </div>
      </div>
    </div>
  );
}

function AppInner() {
  // ?reset en la URL limpia el caché local y recarga desde el servidor
  if(typeof window !== "undefined" && new URLSearchParams(window.location.search).get("reset") !== null){
    try{ localStorage.removeItem("em_data"); localStorage.removeItem("em_last_synced"); localStorage.removeItem("em_last_synced_v2"); }catch(e){}
    window.location.replace(window.location.pathname);
  }
  const [data,setData]=useState(()=>{
    try {
      const saved = localStorage.getItem("em_data");
      if(saved){
        const parsed = JSON.parse(saved);
        // Merge: use saved data but fill in any new keys from initialData
        const merged = {
          ...initialData,
          ...parsed,
          // Always merge new initialData keys that don't exist in saved
          smtp: parsed.smtp || initialData.smtp,
          fichajes: parsed.fichajes || initialData.fichajes,
          // Siempre fusionar contabilidad con todos sus sub-campos por defecto
          contabilidad: { ...initialData.contabilidad, ...(parsed.contabilidad||{}) },
        };
        return merged;
      }
    } catch(e){}
    return initialData;
  });
  const [syncStatus,setSyncStatus]=useState("cargando"); // cargando | ok | guardando | error | offline
  const syncStatusRef = useRef(syncStatus); // copia siempre actualizada para leer dentro de efectos que no dependen de syncStatus
  useEffect(()=>{ syncStatusRef.current = syncStatus; },[syncStatus]);
  const [lastSaveError,setLastSaveError]=useState(null); // motivo real del último fallo de guardado, para no quedarnos solo con el punto rojo sin explicación
  const saveFailCountRef = useRef(0); // fallos consecutivos de guardado; si se acumulan, avisamos en vez de fallar en silencio para siempre
  const lastSyncedRef = useRef({}); // {clientes:"[…]", avisos:"[…]", config:"{…}"} — JSON por sección
  const lastVersionRef = useRef({}); // {clientes:5, avisos:3, config:1} — versión BD por sección
  const dataRef = useRef(data);
  const saveTimerRef = useRef(null);
  useEffect(()=>{ dataRef.current = data; },[data]);
  // lastSyncedRef y lastVersionRef se persisten en localStorage (clave v2) para
  // sobrevivir recargas de página y recuperar cambios que aún no llegaron al servidor.
  const persistirUltimoSincronizado = (jsonPorSeccion) => {
    Object.assign(lastSyncedRef.current, jsonPorSeccion);
    try { localStorage.setItem("em_last_synced_v2", JSON.stringify(lastSyncedRef.current)); } catch(e){}
  };

  // ─── Carga inicial ──────────────────────────────────────────────────────────
  useEffect(()=>{
    let cancelled=false;
    (async()=>{
      try{
        const res = await apiGetSecciones();
        if(cancelled) return;
        if(res.sections && Object.keys(res.sections).length > 0){
          // Cargar bases de comparación guardadas (para detectar cambios pendientes)
          let savedSynced = {};
          try{ savedSynced = JSON.parse(localStorage.getItem("em_last_synced_v2")||"{}"); }catch(e){}
          // Compatibilidad con formato legacy (un único JSON blob)
          if(Object.keys(savedSynced).length === 0){
            try{
              const legacyBase = localStorage.getItem("em_last_synced");
              if(legacyBase){
                const ld = JSON.parse(legacyBase);
                TODAS_SECCIONES.forEach(s=>{ savedSynced[s] = JSON.stringify(extraerSeccion(ld, s)); });
              }
            }catch(e){}
          }
          // Saneamiento post-merge para partes: si el servidor marcó emailEnviado=true,
          // los campos envioProg* siempre se limpian aunque el merge local los restaure.
          // Evita que el estado "programado" reaparezca después de que el cron lo envió.
          const CAMPOS_PROG = ['envioProgFecha','envioProgHora','envioProgEmail',
            'envioProgFirmaNombre','envioProgFirmaImagen','envioProgConforme',
            'envioProgNotas','envioProgPDFBase64','envioProgEmailHtml','envioProgCadenaIds'];
          const sanitizarPartes = (partesArr, remotePartesArr) => {
            if(!Array.isArray(partesArr)) return partesArr;
            const remoteById = new Map((remotePartesArr||[]).map(p=>[p.id,p]));
            return partesArr.map(p => {
              const pr = remoteById.get(p.id);
              if(pr?.emailEnviado && p.envioProgFecha) {
                const limpio = {...p};
                CAMPOS_PROG.forEach(c => { limpio[c] = null; });
                return limpio;
              }
              return p;
            });
          };
          let mergedData = {...dataRef.current};
          const newSynced = {};
          const conflictos = [];
          for(const [seccion, remoteData] of Object.entries(res.sections)){
            const remoteJson = JSON.stringify(remoteData);
            const localData = extraerSeccion(dataRef.current, seccion);
            const localJson = JSON.stringify(localData);
            const baseJson = savedSynced[seccion] || null;
            if(baseJson && localJson !== baseJson && remoteJson !== localJson){
              // Había cambios pendientes que no llegaron al servidor: combinar
              const base = JSON.parse(baseJson);
              let combined = combinarDatosRemotos(base, localData, remoteData, seccion, conflictos);
              if(seccion === 'partes') combined = sanitizarPartes(combined, remoteData);
              mergedData = aplicarSeccion(mergedData, seccion, combined);
            } else {
              mergedData = aplicarSeccion(mergedData, seccion, remoteData);
            }
            newSynced[seccion] = remoteJson;
            lastVersionRef.current[seccion] = res.versions[seccion];
          }
          persistirUltimoSincronizado(newSynced);
          // Al cargar, cerrar avisos que el cron ya resolvió: si un parte fue enviado
          // (emailEnviado:true, sin envioProgFecha) y su aviso sigue en "Pendiente",
          // es porque el cron actuó mientras nadie estaba conectado. Lo cerramos ahora.
          const hoyStr = new Date().toISOString().slice(0,10);
          if(Array.isArray(mergedData.partes) && Array.isArray(mergedData.avisos)){
            let avisosActualizados = false;
            const nuevoAviso = mergedData.avisos.map(a => {
              if(a.estado !== "Pendiente") return a;
              const parteEnviado = mergedData.partes.find(p =>
                p.avisoId === a.id && p.emailEnviado && !p.envioProgFecha
              );
              if(!parteEnviado) return a;
              avisosActualizados = true;
              return { ...a, estado:"Resuelto", fechaResuelto: parteEnviado.fechaEnvio || hoyStr, fechaUltimaIntervencion: parteEnviado.fechaEnvio || hoyStr };
            });
            if(avisosActualizados) mergedData = { ...mergedData, avisos: nuevoAviso };
          }
          setData(prepararDatos(mergedData));
        } else {
          // El servidor no devuelve secciones.
          // SEGURIDAD: si hay datos locales (localStorage de sesión anterior o initialData
          // no vacío), NO sobreescribimos el servidor — podría ser un fallo temporal de la
          // API o un arranque en dominio nuevo. Solo inicializamos si realmente no hay nada.
          const hayDatosLocales = TODAS_SECCIONES.some(s=>{
            const sd = extraerSeccion(dataRef.current, s);
            return Array.isArray(sd) ? sd.length > 0 : Object.keys(sd||{}).length > 0;
          });
          if(hayDatosLocales){
            // Servidor vacío pero hay datos locales: situación anómala.
            // Establecemos baseline para que el guardado automático no machaque el servidor.
            TODAS_SECCIONES.forEach(s=>{
              lastSyncedRef.current[s] = JSON.stringify(extraerSeccion(dataRef.current, s));
            });
            try{ localStorage.setItem("em_last_synced_v2", JSON.stringify(lastSyncedRef.current)); }catch(e){}
            setSyncStatus("error");
            setLastSaveError("El servidor no devolvió datos. Comprueba la conexión antes de continuar.");
            return;
          }
          // Primera vez real (BD vacía): subir initialData al servidor
          for(const s of TODAS_SECCIONES){
            const sd = extraerSeccion(dataRef.current, s);
            try{
              const r = await apiGuardarSeccion(s, sd, null);
              lastVersionRef.current[s] = r.version;
              lastSyncedRef.current[s] = JSON.stringify(sd);
            }catch(e){}
          }
          try{ localStorage.setItem("em_last_synced_v2", JSON.stringify(lastSyncedRef.current)); }catch(e){}
        }
        setSyncStatus("ok");
      }catch(e){
        // Si la carga inicial falla (sin conexión, SSL no listo, error de red…),
        // establecemos el estado local actual como baseline para que el efecto de
        // guardado no lo interprete como "cambios pendientes" y sobreescriba el
        // servidor con datos vacíos cuando la conexión vuelva.
        TODAS_SECCIONES.forEach(s=>{
          if(!lastSyncedRef.current[s])
            lastSyncedRef.current[s] = JSON.stringify(extraerSeccion(dataRef.current, s));
        });
        setSyncStatus("offline");
      }
    })();
    return()=>{ cancelled=true; };
  },[]);

  // Persist ALL data to localStorage on every change (caché local / modo offline)
  useEffect(()=>{
    try { localStorage.setItem("em_data", JSON.stringify(data)); } catch(e){}
  },[data]);

  // ─── Guardado automático por secciones ─────────────────────────────────────
  // Solo guarda las secciones que realmente cambiaron, con debounce de 1200 ms.
  // NO guardamos nada mientras la carga inicial no haya terminado.
  useEffect(()=>{
    if(syncStatus==="cargando") return;
    const cambiadas = TODAS_SECCIONES.filter(s => JSON.stringify(extraerSeccion(data,s)) !== lastSyncedRef.current[s]);
    if(cambiadas.length === 0) return;
    setSyncStatus("guardando");
    if(saveTimerRef.current) clearTimeout(saveTimerRef.current);
    // Función de guardado reutilizable (normal y urgente)
    const doSave = async () => {
      try{
        let dataActual = {...data};
        const conflictos = [];
        const remoto = await apiGetSecciones();
        for(const seccion of cambiadas){
          const localData = extraerSeccion(dataActual, seccion);
          const remoteData = remoto.sections?.[seccion];
          const remoteJson = remoteData !== undefined ? JSON.stringify(remoteData) : null;
          const lastSynced = lastSyncedRef.current[seccion] || null;
          let aGuardar = localData;
          if(lastVersionRef.current[seccion] == null && remoto.versions?.[seccion] != null){
            lastVersionRef.current[seccion] = remoto.versions[seccion];
          }
          if(remoteJson !== null && remoteJson !== lastSynced){
            const base = lastSynced ? JSON.parse(lastSynced) : null;
            const combined = combinarDatosRemotos(base, localData, remoteData, seccion, conflictos);
            aGuardar = combined;
            dataActual = aplicarSeccion(dataActual, seccion, combined);
            lastSyncedRef.current[seccion] = remoteJson;
            lastVersionRef.current[seccion] = remoto.versions?.[seccion];
            if(conflictos.length){
              setSyncStatus("ok"); saveFailCountRef.current=0; setLastSaveError(null);
              setData(prepararDatos(dataActual));
              window.alert("Otro dispositivo ha editado al mismo tiempo lo mismo que tú. Se han combinado los cambios dando prioridad a tu edición; revisa que todo esté correcto.");
              return;
            }
          }
          if(Array.isArray(aGuardar) && aGuardar.length === 0 &&
             Array.isArray(remoteData) && remoteData.length > 0){
            console.warn(`[sync] BLOQUEADO: intento de guardar ${seccion} vacío sobre ${remoteData.length} elementos del servidor.`);
            lastSyncedRef.current[seccion] = remoteJson;
            dataActual = aplicarSeccion(dataActual, seccion, remoteData);
            continue;
          }
          const resp = await apiGuardarSeccion(seccion, aGuardar, lastVersionRef.current[seccion]??null);
          if(resp && resp.conflict){
            const fresco = await apiGetSecciones();
            if(fresco.sections && fresco.sections[seccion] !== undefined){
              const frescoData = fresco.sections[seccion];
              const base2 = lastSyncedRef.current[seccion] ? JSON.parse(lastSyncedRef.current[seccion]) : null;
              const combined2 = combinarDatosRemotos(base2, aGuardar, frescoData, seccion, []);
              dataActual = aplicarSeccion(dataActual, seccion, combined2);
              lastSyncedRef.current[seccion] = JSON.stringify(frescoData);
              lastVersionRef.current[seccion] = fresco.versions?.[seccion];
            }
            continue;
          }
          lastSyncedRef.current[seccion] = JSON.stringify(aGuardar);
          lastVersionRef.current[seccion] = resp.version;
          try{ localStorage.setItem("em_last_synced_v2", JSON.stringify(lastSyncedRef.current)); }catch(e){}
        }
        if(dataActual !== data) setData(prepararDatos(dataActual));
        setSyncStatus("ok"); saveFailCountRef.current=0; setLastSaveError(null);
      }catch(e){
        setSyncStatus("error");
        const motivo = (e && e.message) ? e.message : String(e);
        setLastSaveError(motivo);
        saveFailCountRef.current += 1;
        if(saveFailCountRef.current === 3){
          const sMax = TODAS_SECCIONES.reduce((a,s)=>{ const l=JSON.stringify(extraerSeccion(data,s)).length; return l>a?l:a; },0);
          window.alert("No se están guardando tus cambios en el servidor (error: "+motivo+"; sección más grande: "+(sMax/1024/1024).toFixed(1)+" MB). Sigo reintentando, pero si persiste avisa para no perder cambios.");
        }
      }
    };
    // em-save-now: componentes internos (Parte, Albaran) pueden forzar guardado
    // inmediato sin esperar el debounce — evita pérdida si el técnico cierra la app
    // justo después de enviar el email del parte.
    const handleSaveNow = () => {
      if(saveTimerRef.current) clearTimeout(saveTimerRef.current);
      saveTimerRef.current = setTimeout(doSave, 0);
    };
    window.addEventListener("em-save-now", handleSaveNow, {once:true});
    saveTimerRef.current = setTimeout(doSave, 1200);
    return()=>{
      clearTimeout(saveTimerRef.current);
      window.removeEventListener("em-save-now", handleSaveNow);
    };
  },[data, syncStatus]);

  // ─── Guardado de emergencia (app pasa a segundo plano o se cierra) ──────────
  useEffect(()=>{
    const flushUrgente = ()=>{
      if(saveTimerRef.current){ clearTimeout(saveTimerRef.current); saveTimerRef.current=null; }
      // No guardar si la carga inicial no terminó (syncStatus==="cargando") o si no
      // tenemos ninguna baseline — significaría enviar initialData vacío al servidor.
      if(syncStatusRef.current === "cargando") return;
      if(Object.keys(lastSyncedRef.current).length === 0) return;
      for(const s of TODAS_SECCIONES){
        const sd = extraerSeccion(dataRef.current, s);
        const j = JSON.stringify(sd);
        if(j === lastSyncedRef.current[s]) continue;
        // SEGURIDAD: nunca sobreescribir con array vacío si el baseline tenía datos.
        if(Array.isArray(sd) && sd.length === 0){
          const baseData = lastSyncedRef.current[s] ? JSON.parse(lastSyncedRef.current[s]) : null;
          if(Array.isArray(baseData) && baseData.length > 0) continue;
        }
        // keepalive tiene límite de ~64KB: solo lo usamos para secciones pequeñas.
        // Secciones grandes (clientes con fotos, inventario…) usamos fetch normal.
        const usarKeepalive = j.length < 60000;
        apiGuardarSeccion(s, sd, lastVersionRef.current[s]??null, usarKeepalive ? {keepalive:true} : {}).then(resp=>{
          if(resp && !resp.conflict){
            lastSyncedRef.current[s] = j;
            lastVersionRef.current[s] = resp.version;
            try{ localStorage.setItem("em_last_synced_v2", JSON.stringify(lastSyncedRef.current)); }catch(e){}
          } else if(resp && resp.conflict && resp.version != null){
            // Conflicto de versión: aprendemos la versión actual del servidor para que
            // el siguiente guardado (cuando el usuario vuelva al primer plano) use el
            // número correcto y dispare la fusión en vez de otro sobreescritura ciega.
            lastVersionRef.current[s] = resp.version;
          }
        }).catch(()=>{});
      }
    };
    const onVisibility = ()=>{ if(document.visibilityState==="hidden") flushUrgente(); };
    document.addEventListener("visibilitychange", onVisibility);
    window.addEventListener("pagehide", flushUrgente);
    return()=>{ document.removeEventListener("visibilitychange", onVisibility); window.removeEventListener("pagehide", flushUrgente); };
  },[]);

  // ─── Pull periódico por secciones ──────────────────────────────────────────
  // Solo actualiza las secciones donde NO hay cambios locales pendientes.
  useEffect(()=>{
    const pull = async()=>{
      try{
        const res = await apiGetSecciones();
        if(res.sections){
          let dataActual = dataRef.current;
          let changed = false;
          // Si no tenemos ninguna baseline (p.ej. primer arranque en dominio nuevo
          // tras un fallo de la carga inicial), el remoto es la fuente de verdad y
          // lo cargamos directamente sin comparar — evita que datos vacíos se guarden.
          const sinBaseline = Object.keys(lastSyncedRef.current).length === 0;
          for(const [seccion, remoteData] of Object.entries(res.sections)){
            const remoteJson = JSON.stringify(remoteData);
            const localData = extraerSeccion(dataActual, seccion);
            const localJson = JSON.stringify(localData);
            const lastSynced = lastSyncedRef.current[seccion];
            if(sinBaseline){
              dataActual = aplicarSeccion(dataActual, seccion, remoteData);
              lastSyncedRef.current[seccion] = remoteJson;
              lastVersionRef.current[seccion] = res.versions?.[seccion];
              changed = true;
            } else if(remoteJson !== localJson && localJson === lastSynced){
              // Remoto cambió, nosotros no: tomamos el remoto directamente.
              dataActual = aplicarSeccion(dataActual, seccion, remoteData);
              lastSyncedRef.current[seccion] = remoteJson;
              lastVersionRef.current[seccion] = res.versions?.[seccion];
              changed = true;
            } else if(remoteJson !== lastSynced && localJson !== lastSynced && remoteJson !== localJson){
              // Ambos lados cambiaron desde la última sincronización: fusionamos.
              // Sin esto el borrado remoto (p.ej. tarea eliminada por otro usuario)
              // queda invisible mientras haya cambios locales pendientes, y la
              // tarea puede reaparecer si el cliente guarda antes de recibir el pull.
              const base = lastSynced ? JSON.parse(lastSynced) : null;
              const combined = combinarDatosRemotos(base, localData, remoteData, seccion, []);
              dataActual = aplicarSeccion(dataActual, seccion, combined);
              lastSyncedRef.current[seccion] = remoteJson;
              lastVersionRef.current[seccion] = res.versions?.[seccion];
              changed = true;
            } else if(localJson === lastSynced){
              // Sin cambios locales ni remotos: solo actualizamos el número de versión.
              lastVersionRef.current[seccion] = res.versions?.[seccion];
            }
          }
          if(changed){
            try{ localStorage.setItem("em_last_synced_v2", JSON.stringify(lastSyncedRef.current)); }catch(e){}
            setData(prepararDatos(dataActual));
          }
        }
        setSyncStatus(s => s==="offline" ? "ok" : s);
      }catch(e){ setSyncStatus("offline"); }
    };
    const onVisible = ()=>{ if(document.visibilityState==="visible") pull(); };
    const interval = setInterval(pull, 20000);
    window.addEventListener("focus", pull);
    document.addEventListener("visibilitychange", onVisible);
    return()=>{ clearInterval(interval); window.removeEventListener("focus", pull); document.removeEventListener("visibilitychange", onVisible); };
  },[]);

  // ─── Recarga forzada al detectar nueva versión de código ───────────────────
  useEffect(()=>{
    const comprobar = async()=>{
      try{
        const res = await fetch("/version.json?t="+Date.now(), { cache:"no-store" });
        if(!res.ok) return;
        const json = await res.json();
        if(json && json.build && json.build !== __BUILD_ID__){
          if(syncStatusRef.current === "ok"){
            window.location.reload();
          } else {
            // Intentar guardar las secciones pendientes antes de recargar
            const hayCambios = TODAS_SECCIONES.some(s => JSON.stringify(extraerSeccion(dataRef.current,s)) !== lastSyncedRef.current[s]);
            if(hayCambios){
              for(const s of TODAS_SECCIONES){
                const sd = extraerSeccion(dataRef.current, s);
                const sdJson = JSON.stringify(sd);
                if(sdJson === lastSyncedRef.current[s]) continue;
                try{
                  // keepalive tiene límite de 64KB en el navegador — para secciones grandes
                  // usamos fetch normal (la página aún no se ha cerrado, solo va a recargarse).
                  const usarKeepalive = sdJson.length < 60000;
                  const resp = await apiGuardarSeccion(s, sd, lastVersionRef.current[s]??null, usarKeepalive ? {keepalive:true} : {});
                  if(resp && !resp.conflict){ lastSyncedRef.current[s]=sdJson; lastVersionRef.current[s]=resp.version; }
                }catch(e){}
              }
              try{ localStorage.setItem("em_last_synced_v2", JSON.stringify(lastSyncedRef.current)); }catch(e){}
            }
            window.location.reload();
          }
        }
      }catch(e){ /* sin conexión: no forzamos nada */ }
    };
    // Comprobamos también justo al montar (cubre pestañas que llevan abiertas
    // desde antes de un despliegue y todavía no han cambiado de pestaña ni de
    // foco), y cada 30s en vez de cada 5 min: así un despliegue nuevo llega a
    // todo el mundo casi al momento en vez de esperar hasta 5 minutos.
    comprobar();
    const interval = setInterval(comprobar, 30000);
    const onVisible = ()=>{ if(document.visibilityState==="visible") comprobar(); };
    document.addEventListener("visibilitychange", onVisible);
    return ()=>{ clearInterval(interval); document.removeEventListener("visibilitychange", onVisible); };
  },[]);

  // Botón manual de "Actualizar datos" (junto al punto de color de la cabecera).
  // Primero comprueba si hay una versión de código más nueva publicada (si la
  // hay, recarga directamente: así el usuario tiene la garantía de quedar al
  // día sin esperar al sondeo automático de 5 min); si el código ya está al
  // día, simplemente trae los datos más recientes del servidor.
  const [actualizando,setActualizando]=useState(false);
  const actualizarManual = async ()=>{
    if(actualizando) return;
    setActualizando(true);
    try{
      try{
        const res = await fetch("/version.json?t="+Date.now(), { cache:"no-store" });
        if(res.ok){
          const json = await res.json();
          if(json && json.build && json.build !== __BUILD_ID__){
            // Guardar antes de recargar para no perder cambios pendientes
            const jsonActual = JSON.stringify(dataRef.current);
            if(jsonActual !== lastSyncedRef.current){
              try{
                const resp = await apiSaveData(dataRef.current, lastVersionRef.current);
                if(resp && !resp.conflict){ persistirUltimoSincronizado(jsonActual); lastVersionRef.current = resp.version; }
              }catch(e){}
            }
            window.location.reload();
            return;
          }
        }
      }catch(e){}
      const remoto = await apiGetData();
      if(remoto.data){
        const remoteJson = JSON.stringify(remoto.data);
        const localJson = JSON.stringify(dataRef.current);
        if(remoteJson !== localJson){
          // Si lo local difiere de lo que sabíamos guardado en el servidor, no lo
          // descartamos sin más (podría ser una edición que el guardado automático
          // seguía reintentando sin éxito): la combinamos igual que en la carga inicial.
          if(localJson !== lastSyncedRef.current){
            const base = lastSyncedRef.current ? JSON.parse(lastSyncedRef.current) : null;
            const conflictos = [];
            const combinado = prepararDatos(combinarDatosRemotos(base, dataRef.current, remoto.data, "raiz", conflictos));
            persistirUltimoSincronizado(remoteJson);
            lastVersionRef.current = remoto.version;
            setData(combinado);
          } else {
            persistirUltimoSincronizado(remoteJson);
            lastVersionRef.current = remoto.version;
            setData(prepararDatos(remoto.data));
          }
        } else {
          lastVersionRef.current = remoto.version;
        }
      }
      setSyncStatus(s => s==="offline" ? "ok" : s);
    }catch(e){
      setSyncStatus("offline");
    }finally{
      setActualizando(false);
    }
  };

  const [articuloPublico]=useState(()=>{
    try { return new URLSearchParams(window.location.search).get("articulo"); } catch(e) { return null; }
  });
  const [maquinaPublica]=useState(()=>{
    try { return new URLSearchParams(window.location.search).get("maquina"); } catch(e) { return null; }
  });
  const [presupuestoAceptar]=useState(()=>{
    try { return new URLSearchParams(window.location.search).get("aceptar"); } catch(e) { return null; }
  });
  // Id de tarea recibido por enlace externo (botón "Ver tarea en la app" del
  // email automático). A diferencia de articulo/maquina, requiere sesión
  // iniciada: se consume justo después de loguearse (ver efecto más abajo).
  const [tareaUrlInicial]=useState(()=>{
    try { return new URLSearchParams(window.location.search).get("tarea"); } catch(e) { return null; }
  });
  const [user,setUser]=useState(null);
  // "user" se fija una vez al iniciar sesión (con la foto de data.usuarios de ese
  // momento) y nunca se volvía a tocar salvo edición manual en "Mi cuenta". Si en
  // ese momento los datos locales eran una copia vieja de localStorage (antes de
  // que termine de llegar la versión fresca del servidor), "user" se queda
  // congelado con campos desfasados (p.ej. el email guardado desde otro
  // dispositivo) aunque "data" se corrija segundos después. Mantenemos "user"
  // sincronizado con su registro real en data.usuarios en todo momento.
  useEffect(()=>{
    if(!user)return;
    const actual=data.usuarios.find(u=>u.id===user.id);
    if(actual&&JSON.stringify(actual)!==JSON.stringify(user))setUser(actual);
  },[data.usuarios,user]);
  const [active,setActive]=useState("asistencia");
  const [notifOpen,setNotifOpen]=useState(false);
  const [menuOpen,setMenuOpen]=useState(false); // sidebar móvil drawer
  const [cuentaOpen,setCuentaOpen]=useState(false); // modal "Mi cuenta"
  const [docFiltro,setDocFiltro]=useState(null); // filtro pendiente al entrar en Documentación desde la ficha de una máquina
  const irADocMaquina=filtro=>{setDocFiltro(filtro);setActive("documentacion");};
  const notifRef=useRef(null);
  const [isMobile,setIsMobile]=useState(()=>window.innerWidth<768);
  const [isTablet,setIsTablet]=useState(()=>window.innerWidth>=768&&window.innerWidth<1024);
  useEffect(()=>{
    const h=()=>{ setIsMobile(window.innerWidth<768); setIsTablet(window.innerWidth>=768&&window.innerWidth<1024); };
    window.addEventListener("resize",h); return()=>window.removeEventListener("resize",h);
  },[]);
  useEffect(()=>{
    const id = "em-responsive";
    if(document.getElementById(id)) return;
    const style = document.createElement("style");
    style.id = id;
    const css = [
      "*, *::before, *::after { box-sizing: border-box !important; }",
      "html, body { overflow-x: hidden !important; max-width: 100vw !important; }",
      "img, video, canvas, svg { max-width: 100% !important; }",
      "@media (max-width: 767px) {",
      "  .ficha-grid { grid-template-columns: 1fr !important; }",
      "  input, select, textarea { max-width: 100% !important; font-size: 16px !important; }",
      "}"
    ].join("\n");
    style.textContent = css;
    document.head.appendChild(style);
    return () => { const el = document.getElementById(id); if(el) el.remove(); };
  }, []);
  const [popupQueue,setPopupQueue]=useState([]);
  const [totalPopups,setTotalPopups]=useState(0);
  // Cada vez que el usuario inicia sesión (login real: user pasa de null a un usuario) se
  // construye una cola de pop-ups que tiene que ir leyendo y cerrando uno a uno: 1) una por
  // cada tarea pendiente (las completadas nunca se notifican), 2) avisos nuevos agrupados
  // (solo se avisan la primera vez: una vez leídos quedan marcados y no vuelven a salir),
  // 3) mensajes de chat nuevos + resumen de todos los avisos pendientes, juntos.
  // Las tareas pendientes y el resumen de avisos son consultas en vivo, así que se repiten
  // en cada login (no solo la primera vez por sesión de navegador).
  // La campanita deja de llevar contador de "no leídas": cada pop-up cerrado queda registrado
  // y marcado como leído, así que la campanita pasa a ser solo el historial en modo lista.
  // IMPORTANTE: si el login ocurre antes de que termine la carga inicial desde el
  // servidor (syncStatus==="cargando"), "data" puede ser todavía la copia vieja de
  // localStorage (de horas o días antes en ese dispositivo): la cola saldría con
  // menos avisos de los que hay en realidad y con tareas ya completadas en otro
  // dispositivo mostradas como pendientes. Por eso esperamos a que la carga
  // termine, y solo construimos la cola una vez por login (popupsHechosRef).
  const popupsHechosRef=useRef(null);
  useEffect(()=>{
    if(!user){popupsHechosRef.current=null;return;}
    if(syncStatus==="cargando")return;
    if(popupsHechosRef.current===user.id)return;
    popupsHechosRef.current=user.id;
    const misNotifsIniciales=data.notificaciones[user.id]||[];
    const cola=[];
    // El nombre del cliente puede venir guardado en el propio aviso (n.clienteNombre, en los
    // avisos creados tras este cambio), o si no, se busca: 1) por el aviso original (n.avisoId)
    // y su clienteId, 2) extrayéndolo del texto del mensaje ("Cliente: X · ..."), que es como
    // se guardaban los avisos antiguos antes de añadir el campo clienteNombre.
    const clienteDeNotifAviso=n=>{
      if(n.clienteNombre)return n.clienteNombre;
      const aviso=n.avisoId&&data.avisos.find(a=>a.id===n.avisoId);
      if(aviso)return data.clientes.find(c=>c.id===aviso.clienteId)?.nombreEmpresa||"sin cliente";
      const m=n.mensaje&&n.mensaje.match(/Cliente:\s*([^·]+)/);
      return m?m[1].trim():"sin cliente";
    };
    // Municipio del cliente asociado al aviso de una notificación (para mostrarlo
    // bajo el nombre del cliente en el pop-up). Solo se puede resolver cuando se
    // conoce el aviso (y por tanto el clienteId); si no, no se muestra nada.
    const municipioDeNotifAviso=n=>{
      const aviso=n.avisoId&&data.avisos.find(a=>a.id===n.avisoId);
      if(!aviso)return null;
      return data.clientes.find(c=>c.id===aviso.clienteId)?.localidad||null;
    };
    // 1) AVISOS NUEVOS: uno por uno. Solo se muestran la primera vez — al cerrar el pop-up
    // (ver cerrarPopup) quedan marcados como leídos y nunca vuelven a aparecer.
    // Color por tipo de pop-up: rojo para tareas (lo más urgente, hay que hacer
    // algo), amarillo para avisos y stock (información a revisar). Se usa tanto
    // en el borde de la tarjeta como en el icono del sobre, para que todo el
    // pop-up tenga un único color coherente con su categoría.
    const COLOR_TAREA="#ef4444", COLOR_AVISO="#f59e0b";
    const avisosNuevos=misNotifsIniciales.filter(n=>!n.leida&&n.tipo==="nuevo_aviso");
    avisosNuevos.forEach(n=>{
      cola.push({
        id:"avn_"+n.id,notifId:n.id,color:COLOR_AVISO,categoria:"AVISOS NUEVOS",
        linea:n.avisoTitulo||n.titulo.replace("🔔 Nuevo aviso: ",""),cliente:clienteDeNotifAviso(n),
        municipio:municipioDeNotifAviso(n),
        titulo:n.titulo,mensaje:n.mensaje
      });
    });
    // 2) TAREAS: un único pop-up con TODAS las tareas pendientes (de empresa o propia)
    // que no estén completadas, en formato lista (mismo formato que el resumen de
    // avisos: punto de color a la izquierda, título en mayúsculas y debajo el
    // vencimiento). Antes salía una por una, lo que era muy repetitivo si había
    // varias; ahora se agrupan en una sola pantalla, scrolleable si hay más de 8.
    // Se repite en cada conexión mientras sigan pendientes (es una consulta en vivo, no "nueva").
    const tareasPend=data.tareas.filter(t=>(t.asignadoId===user.id||t.esEmpresa)&&t.estado!=="Completada");
    if(tareasPend.length>0){
      const listaTareas=tareasPend.map(t=>({texto:t.titulo,vence:t.vence?fmtVenceCompleto(t.vence):null}));
      cola.push({
        id:"tp_resumen",color:COLOR_TAREA,categoria:"TAREAS",
        lista:listaTareas,
        titulo:"⏳ Tareas pendientes",
        mensaje:`${tareasPend.length} tarea${tareasPend.length>1?"s":""} pendiente${tareasPend.length>1?"s":""}:\n`+listaTareas.map(l=>"· "+l.texto+(l.vence?" — "+l.vence:"")).join("\n"),
        sintetico:true,logTipo:"tareas_pendientes_resumen"
      });
    }
    // 3) Por último, resumen conjunto de todos los avisos pendientes (+ mensajes de chat
    // nuevos si los hay). Es siempre el cierre de la conexión, también una consulta en vivo.
    const chatsNuevos=misNotifsIniciales.filter(n=>!n.leida&&n.tipo==="chat");
    const avisosPend=data.avisos.filter(a=>a.estado!=="Resuelto"&&a.estado!=="Cancelado");
    if(chatsNuevos.length>0||avisosPend.length>0){
      // Versión estructurada (texto + cliente por separado) para poder pintar el
      // pop-up con el nombre del cliente en negrita; versión en texto plano (unida
      // con guion) para el mensaje que se guarda en el historial de notificaciones.
      const listaEstructurada=avisosPend.map(a=>{
        const c=data.clientes.find(c=>c.id===a.clienteId);
        return{texto:a.titulo,cliente:c?.nombreEmpresa||"sin cliente",municipio:c?.localidad||null};
      });
      const listaPlana=listaEstructurada.map(l=>l.texto+" — "+l.cliente);
      const partes=[];
      if(chatsNuevos.length>0)partes.push(`💬 Últimos mensajes de chat recibidos (${chatsNuevos.length}) — quién escribe y en qué canal:\n`+chatsNuevos.map(n=>"· "+n.titulo.replace("💬 ","")+" → \""+n.mensaje+"\"").join("\n"));
      if(avisosPend.length>0)partes.push(`📋 ${avisosPend.length} aviso${avisosPend.length>1?"s":""} pendiente${avisosPend.length>1?"s":""}:\n`+listaPlana.map(l=>"· "+l).join("\n"));
      cola.push({
        id:"chat_av",notifIds:chatsNuevos.map(n=>n.id),color:COLOR_AVISO,categoria:"AVISOS",
        linea:chatsNuevos.length>0?`${chatsNuevos.length} mensaje${chatsNuevos.length>1?"s":""} de chat nuevo${chatsNuevos.length>1?"s":""}`:null,
        lista:avisosPend.length>0?listaEstructurada:null,
        titulo:"📨 Resumen de tu conexión",mensaje:partes.join("\n\n"),
        sintetico:avisosPend.length>0,logTipo:"avisos_pendientes_resumen"
      });
    }
    if(cola.length>0){setPopupQueue(cola);setTotalPopups(cola.length);}
  },[user,syncStatus]);
  const cerrarPopup=()=>{
    const actual=popupQueue[0];
    if(actual){
      setData(d=>{
        const propios=d.notificaciones[user.id]||[];
        const idsAleer=new Set([actual.notifId,...(actual.notifIds||[])].filter(Boolean));
        let actualizados=idsAleer.size>0?propios.map(n=>idsAleer.has(n.id)?{...n,leida:true}:n):propios;
        if(actual.sintetico){
          const registro=crearNotif(user.id,actual.logTipo||"popup",actual.titulo,actual.mensaje);
          registro.leida=true;
          actualizados=[registro,...actualizados];
        }
        return {...d,notificaciones:{...d.notificaciones,[user.id]:actualizados}};
      });
    }
    setPopupQueue(q=>q.slice(1));
  };
  const [avisoAAbrir,setAvisoAAbrir]=useState(null);
  const irAAviso=id=>{setAvisoAAbrir(id);setActive("asistencia");};
  const [clienteAAbrir,setClienteAAbrir]=useState(null);
  const irACliente=id=>{setClienteAAbrir(id);setActive("clientes");};
  const [parteAAbrir,setParteAAbrir]=useState(null);
  const irAParte=id=>{setParteAAbrir(id);setActive("partes");};
  const [maquinaVistaAbrir,setMaquinaVistaAbrir]=useState(null); // {clienteId, maquinaId}
  const irAMaquina=(clienteId,maquinaId)=>{setMaquinaVistaAbrir({clienteId,maquinaId});setActive("maquinas");};
  const [tareaAAbrir,setTareaAAbrir]=useState(null);
  const irATarea=id=>{setTareaAAbrir(id);setActive("tareas");};
  // Si se ha llegado con ?tarea=ID en la URL (enlace del email automático), en
  // cuanto haya sesión abierta navegamos directamente a esa tarea.
  useEffect(()=>{
    if(!user||!tareaUrlInicial)return;
    irATarea(parseInt(tareaUrlInicial));
  },[user]);
  const onNuevoAviso=aviso=>{
    setData(d=>{
      const nn={...d.notificaciones};
      const clienteNombre=d.clientes.find(c=>c.id===aviso.clienteId)?.nombreEmpresa||"—";
      d.usuarios.filter(u=>u.activo).forEach(u=>{
        const n=crearNotif(u.id,"nuevo_aviso",
          `🔔 Nuevo aviso: ${aviso.titulo}`,
          `Cliente: ${clienteNombre} · Prioridad: ${aviso.prioridad} · Asignado: ${listaNombres(aviso,"asignados","asignado").join(" y ")||"Sin asignar"}`,
          {avisoId:aviso.id,clienteNombre,avisoTitulo:aviso.titulo}
        );
        nn[u.id]=[n,...(nn[u.id]||[])];
      });
      return{...d,notificaciones:nn};
    });
  };
  const onPrueba=async()=>{
    const act=data.avisos.filter(a=>a.estado!=="Resuelto"&&a.estado!=="Cancelado");
    const n=crearNotif(user.id,"diario","📋 Resumen manual",`${act.length} avisos activos`);
    setData(d=>({...d,notificaciones:{...d.notificaciones,[user.id]:[n,...(d.notificaciones[user.id]||[])]}}));
    const destino=data.smtp?.from||data.smtp?.user;
    if(!destino){alert("Configura y guarda el SMTP antes de enviar la prueba.");return;}
    try{
      await apiSendMail({
        to: destino,
        subject: "Prueba SMTP — Europea de Maquinaria",
        html: "<p>Esto es un email de prueba.</p><p>Avisos activos: <strong>"+act.length+"</strong>.</p><p>Si lo has recibido, el SMTP está bien configurado.</p>",
      });
      alert("Email de prueba enviado a "+destino+".");
    }catch(e){
      alert("No se pudo enviar el email de prueba.\n\n"+e.message);
    }
  };
  if(presupuestoAceptar) return <AceptarPresupuestoPublico token={presupuestoAceptar}/>;
  if(articuloPublico){
    if(!user)return <Login usuarios={data.usuarios} onLogin={u=>setUser(u)}/>;
    return <FichaPublicaArticulo codigo={articuloPublico} data={data} cargando={syncStatus==="cargando"}/>;
  }
  if(maquinaPublica){
    // Igual que la ficha de artículo: no se muestra ningún dato (ni el nombre del
    // cliente) hasta que la persona que escanea el QR inicia sesión en la app.
    if(!user)return <Login usuarios={data.usuarios} onLogin={u=>setUser(u)}/>;
    return <FichaPublicaMaquina codigo={maquinaPublica} data={data} cargando={syncStatus==="cargando"}/>;
  }
  if(!user)return <Login usuarios={data.usuarios} onLogin={u=>{setUser(u);setActive("asistencia");}}/>;
  const addNotif=(userId,tipo,titulo,mensaje)=>{
    const n=crearNotif(userId,tipo,titulo,mensaje);
    setData(d=>({...d,notificaciones:{...d.notificaciones,[userId]:[n,...(d.notificaciones[userId]||[])]}}));
  };
  // La campanita ya no lleva contador de "no leídas": todo lo relevante se informa mediante
  // los pop-ups secuenciales al conectar (ver popupQueue/cerrarPopup más arriba), que se marcan
  // como leídos al cerrarlos. La campanita es ahora solo el historial en modo lista.
  const misNotifs=data.notificaciones[user.id]||[];
  const avisosActivos=data.avisos.filter(a=>a.estado!=="Resuelto"&&a.estado!=="Cancelado").length;
  // El badge de "Avisos" en la nav debe reflejar solo los avisos activos: antes se le sumaba
  // también el recuento de "reparaciones" (un dato antiguo que no se gestiona desde ninguna
  // pantalla), lo que hacía que con p.ej. 2 avisos activos el número mostrado fuera 4.
  const asistenciaActiva=avisosActivos;
  const misTareasPend=data.tareas.filter(t=>(t.asignadoId===user.id||t.esEmpresa)&&t.estado!=="Completada").length;
  const navV=NAV_ITEMS.filter(n=>puedeVer(user.rol,n.id));
  const bottomNav = navV.slice(0,4);
  const moreNav   = navV.slice(4);
  const navBadge = id => {
    if(id==="asistencia"&&asistenciaActiva>0) return asistenciaActiva;
    if(id==="tareas"&&misTareasPend>0) return misTareasPend;
    return null;
  };
  const handleNav = id => { setActive(id); setMenuOpen(false); };
  const Topbar = () => (
    <div style={{height:isMobile?"calc(52px + env(safe-area-inset-top))":48,background:"#0a0f1a",borderBottom:"1px solid #1a2236",display:"flex",alignItems:"center",justifyContent:"space-between",padding:isMobile?"env(safe-area-inset-top) 14px 0":"0 20px",flexShrink:0,position:"relative",zIndex:10}}>
      {isMobile?(
        <>
          {/* Logo móvil */}
          <div style={{display:"flex",alignItems:"center",gap:8}}>
            <img src={LOGO_URL} style={{width:28,height:28,borderRadius:7,objectFit:"contain"}} alt="EM"/>
            <div style={{fontWeight:900,fontSize:12,color:"#f1f3f9",letterSpacing:".3px"}}>EUROPEA</div>
          </div>
          {/* Titulo módulo activo */}
          <div style={{position:"absolute",left:"50%",transform:"translateX(-50%)",color:"#f1f3f9",fontWeight:700,fontSize:14}}>
            {navV.find(n=>n.id===active)?.label||""}
          </div>
          {/* Notifs + avatar */}
          <div style={{display:"flex",alignItems:"center",gap:6}}>
            <div title={syncStatus==="error" && lastSaveError ? `Error al guardar: ${lastSaveError} (reintentando)` : SYNC_LABELS[syncStatus]} style={{width:7,height:7,borderRadius:"50%",background:SYNC_COLORS[syncStatus]}}/>
            <button onClick={actualizarManual} disabled={actualizando} title="Actualizar datos" style={{background:"transparent",border:"none",cursor:actualizando?"default":"pointer",color:"#e4e9f6",display:"flex",alignItems:"center",padding:3,opacity:actualizando?0.5:1}}>
              <Icon name="refresh" size={14}/>
            </button>
            <div ref={notifRef} style={{position:"relative"}}>
              <button onClick={()=>setNotifOpen(p=>!p)} style={{background:notifOpen?"#1a2236":"transparent",border:"1px solid "+(notifOpen?"#2a3550":"transparent"),borderRadius:7,padding:"5px 7px",cursor:"pointer",color:"#e4e9f6",display:"flex",alignItems:"center",gap:3}}>
                <Icon name="bell" size={16}/>
              </button>
              {notifOpen&&<NotifPanel notifs={misNotifs} onClose={()=>setNotifOpen(false)} onIrAlChat={()=>{setActive("chat");setNotifOpen(false);}}/>}
            </div>
            <Avatar u={user} size={28} fontSize={11} onClick={()=>setCuentaOpen(true)}/>
          </div>
        </>
      ):(
        <>
          <div style={{color:"#f1f3f9",fontWeight:700,fontSize:15}}>
            {navV.find(n=>n.id===active)?.label||""}
          </div>
          <div style={{display:"flex",alignItems:"center",gap:10}}>
          <div title={SYNC_LABELS[syncStatus]} style={{width:7,height:7,borderRadius:"50%",background:SYNC_COLORS[syncStatus]}}/>
          <button onClick={actualizarManual} disabled={actualizando} title="Actualizar datos" style={{background:"transparent",border:"none",cursor:actualizando?"default":"pointer",color:"#e4e9f6",display:"flex",alignItems:"center",padding:4,opacity:actualizando?0.5:1}}>
            <Icon name="refresh" size={15}/>
          </button>
          <div ref={notifRef} style={{position:"relative"}}>
            <button onClick={()=>setNotifOpen(p=>!p)} style={{background:notifOpen?"#1a2236":"transparent",border:"1px solid "+(notifOpen?"#2a3550":"transparent"),borderRadius:7,padding:"6px 8px",cursor:"pointer",color:"#e4e9f6",display:"flex",alignItems:"center",gap:4}}>
              <Icon name="bell" size={16}/>
            </button>
            {notifOpen&&<NotifPanel notifs={misNotifs} onClose={()=>setNotifOpen(false)} onIrAlChat={()=>{setActive("chat");setNotifOpen(false);}}/>}
          </div>
          </div>
        </>
      )}
    </div>
  );
  const Sidebar = () => (
    <aside style={{width:isTablet?64:248,background:"#0a0f1a",borderRight:"1px solid #1a2236",display:"flex",flexDirection:"column",flexShrink:0,transition:"width .2s"}}>
      {/* Logo */}
      <div style={{padding:isTablet?"10px 8px":"10px 13px 9px",borderBottom:"1px solid #1a2236",display:"flex",alignItems:"center",justifyContent:isTablet?"center":"flex-start",gap:9,flexShrink:0}}>
        <img src={LOGO_URL} style={{width:30,height:30,borderRadius:8,objectFit:"contain",flexShrink:0}} alt="EM"/>
        {!isTablet&&<div><div style={{fontWeight:900,fontSize:12,color:"#f1f3f9",letterSpacing:".4px"}}>EUROPEA</div><div style={{fontSize:10,color:"#e4e9f6",letterSpacing:".9px"}}>DE MAQUINARIA</div></div>}
      </div>
      {/* Nav — flex column para que los items llenen el espacio sin scroll */}
      <nav style={{padding:"4px 5px",flex:1,overflow:"hidden",display:"flex",flexDirection:"column"}}>
        {navV.map(n=>{
          const badge=navBadge(n.id);
          return(
            <button key={n.id} onClick={()=>handleNav(n.id)} title={isTablet?n.label:""}
              style={{width:"100%",flex:1,minHeight:0,display:"flex",alignItems:"center",justifyContent:isTablet?"center":"space-between",padding:isTablet?"6px":"4px 10px",borderRadius:7,border:"none",cursor:"pointer",background:active===n.id?n.color+"22":"transparent",color:active===n.id?n.color:"#e4e9f6",fontWeight:active===n.id?700:400,fontSize:14,position:"relative",transition:"background .12s"}}>
              <span style={{display:"flex",alignItems:"center",gap:isTablet?0:9}}>
                <Icon name={n.icon} size={isTablet?20:16}/>
                {!isTablet&&n.label}
              </span>
              {badge&&!isTablet&&<span style={{background:n.id==="tareas"?"#8b5cf6":"#ef4444",color:"#fff",borderRadius:9,padding:"1px 7px",fontSize:11,fontWeight:800}}>{badge}</span>}
              {badge&&isTablet&&<span style={{position:"absolute",top:4,right:4,background:n.id==="tareas"?"#8b5cf6":"#ef4444",color:"#fff",borderRadius:8,padding:"0 4px",fontSize:9,fontWeight:800,minWidth:14,textAlign:"center"}}>{badge}</span>}
            </button>
          );
        })}
      </nav>
      {/* Usuario */}
      <div style={{padding:isTablet?"6px 5px":"7px 10px",borderTop:"1px solid #1a2236",flexShrink:0}}>
        {isTablet?(
          <button onClick={()=>setUser(null)} title="Cerrar sesión" style={{width:"100%",background:"#1a2236",border:"none",borderRadius:6,padding:"7px",color:"#e4e9f6",cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center"}}><Icon name="logout" size={14}/></button>
        ):(
          <>
            <div onClick={()=>setCuentaOpen(true)} title="Mi cuenta" style={{display:"flex",alignItems:"center",gap:8,marginBottom:5,cursor:"pointer"}}>
              <Avatar u={user} size={27} fontSize={11}/>
              <div style={{flex:1,minWidth:0}}><div style={{color:"#f1f3f9",fontSize:12,fontWeight:700,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{user.nombre}</div><RolBadge rol={user.rol}/></div>
            </div>
            <button onClick={()=>setUser(null)} style={{width:"100%",background:"#1a2236",border:"1px solid #2a3550",borderRadius:7,padding:"5px",color:"#e4e9f6",fontSize:11,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",gap:6,fontWeight:600}}><Icon name="logout" size={12}/>Cerrar sesión</button>
            <div style={{marginTop:5,textAlign:"center",color:"#e4e9f6",fontSize:9,lineHeight:1.4,letterSpacing:"0.3px"}}>Software por <span style={{color:"#f59e0b",fontWeight:700}}>Raúl Ibars</span><br/>2026 · v2.0 · {__BUILD_DATE__}</div>
          </>
        )}
      </div>
    </aside>
  );
  const BottomNav = () => (
    <nav style={{position:"fixed",bottom:0,left:0,right:0,height:60,background:"#0a0f1a",borderTop:"1px solid #1a2236",display:"flex",alignItems:"stretch",zIndex:100,paddingBottom:"env(safe-area-inset-bottom)"}}>
      {bottomNav.map(n=>{
        const badge=navBadge(n.id);
        const isActive=active===n.id&&!menuOpen;
        return(
          <button key={n.id} onClick={()=>handleNav(n.id)}
            style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",border:"none",background:"transparent",color:isActive?n.color:"#e4e9f6",cursor:"pointer",gap:3,position:"relative",padding:"6px 0"}}>
            <div style={{position:"relative"}}>
              <Icon name={n.icon} size={20}/>
              {badge&&<span style={{position:"absolute",top:-5,right:-7,background:n.id==="tareas"?"#8b5cf6":"#ef4444",color:"#fff",borderRadius:8,padding:"0 4px",fontSize:9,fontWeight:800,minWidth:15,textAlign:"center"}}>{badge}</span>}
            </div>
            <span style={{fontSize:9,fontWeight:isActive?700:400,letterSpacing:".2px"}}>{n.label.split(" ")[0]}</span>
            {isActive&&<div style={{position:"absolute",top:0,left:"50%",transform:"translateX(-50%)",width:28,height:3,borderRadius:"0 0 3px 3px",background:n.color}}/>}
          </button>
        );
      })}
      {/* Botón "Más" para el resto */}
      {moreNav.length>0&&(
        <button onClick={()=>setMenuOpen(p=>!p)}
          style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",border:"none",background:"transparent",color:menuOpen||(moreNav.some(n=>n.id===active))?"#f59e0b":"#e4e9f6",cursor:"pointer",gap:3,padding:"6px 0",position:"relative"}}>
          {moreNav.some(n=>n.id===active)&&!menuOpen&&<div style={{position:"absolute",top:0,left:"50%",transform:"translateX(-50%)",width:28,height:3,borderRadius:"0 0 3px 3px",background:"#f59e0b"}}/>}
          <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(min(260px,100%),1fr))",gap:2,width:18,height:18}}>
            {[0,1,2,3].map(i=><div key={i} style={{background:menuOpen||(moreNav.some(n=>n.id===active))?"#f59e0b":"#e4e9f6",borderRadius:2}}/>)}
          </div>
          <span style={{fontSize:9,fontWeight:700,letterSpacing:".2px"}}>Más</span>
        </button>
      )}
    </nav>
  );
  const MoreDrawer = () => menuOpen&&(
    <>
      <div onClick={()=>setMenuOpen(false)} style={{position:"fixed",top:0,left:0,right:0,bottom:0,background:"rgba(0,0,0,.5)",zIndex:110}}/>
      <div style={{position:"fixed",bottom:60,left:0,right:0,background:"#0a0f1a",borderTop:"1px solid #1a2236",zIndex:120,borderRadius:"16px 16px 0 0",padding:"16px 12px 8px"}}>
        <div style={{width:36,height:4,borderRadius:2,background:"#2a3550",margin:"0 auto 16px"}}/>
        <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(min(100px,100%),1fr))",gap:8,marginBottom:16}}>
          {moreNav.map(n=>{
            const badge=navBadge(n.id);
            return(
              <button key={n.id} onClick={()=>handleNav(n.id)}
                style={{display:"flex",flexDirection:"column",alignItems:"center",gap:5,padding:"10px 4px",borderRadius:10,border:"none",background:active===n.id?n.color+"20":"#151b2a",color:active===n.id?n.color:"#e4e9f6",cursor:"pointer",position:"relative"}}>
                <div style={{position:"relative"}}><Icon name={n.icon} size={22}/>{badge&&<span style={{position:"absolute",top:-5,right:-7,background:"#ef4444",color:"#fff",borderRadius:8,padding:"0 4px",fontSize:9,fontWeight:800}}>{badge}</span>}</div>
                <span style={{fontSize:10,fontWeight:active===n.id?700:400,textAlign:"center",lineHeight:1.2}}>{n.label}</span>
              </button>
            );
          })}
        </div>
        {/* Usuario info + logout en el drawer */}
        <div style={{borderTop:"1px solid #1a2236",paddingTop:12,display:"flex",alignItems:"center",justifyContent:"space-between"}}>
          <div onClick={()=>{setCuentaOpen(true);setMenuOpen(false);}} title="Mi cuenta" style={{display:"flex",alignItems:"center",gap:8,cursor:"pointer"}}>
            <Avatar u={user} size={32} fontSize={13}/>
            <div><div style={{color:"#f1f3f9",fontSize:13,fontWeight:700}}>{user.nombre}</div><RolBadge rol={user.rol}/></div>
          </div>
          <button onClick={()=>setUser(null)} style={{background:"#1a2236",border:"1px solid #2a3550",borderRadius:8,padding:"7px 12px",color:"#e4e9f6",fontSize:12,cursor:"pointer",display:"flex",alignItems:"center",gap:5,fontWeight:600}}><Icon name="logout" size={12}/>Salir</button>
        </div>
      </div>
    </>
  );
  return (
    <div style={{display:"flex",flexDirection:"column",height:"100vh",background:"#0d1117",fontFamily:"'DM Sans','Segoe UI',sans-serif",color:"#f1f3f9",overflow:"hidden",maxWidth:"100vw"}}>
      <Topbar/>
      <div style={{display:"flex",flex:1,overflow:"hidden"}}>
        {!isMobile&&<Sidebar/>}
        <main style={{flex:1,overflow:(active==="chat"&&isMobile)?"hidden":"auto",overflowX:"hidden",padding:isMobile?"14px 10px 76px":"20px 24px",maxWidth:"100%",...((active==="chat"&&isMobile)?{display:"flex",flexDirection:"column",minHeight:0}:{})}}>
          {active==="dashboard"&&<Dashboard data={data} setActive={setActive} userActual={user}/>}
          {active==="asistencia"&&puedeVer(user.rol,"asistencia")&&<AvisosAsistencia data={data} setData={setData} userActual={user} onNuevoAviso={onNuevoAviso} abrirAvisoId={avisoAAbrir} onAbrirAvisoId={()=>setAvisoAAbrir(null)} irACliente={irACliente} irAMaquina={irAMaquina}/>}
          {active==="clientes"&&puedeVer(user.rol,"clientes")&&<Clientes data={data} setData={setData} onIrADocMaquina={irADocMaquina} abrirClienteId={clienteAAbrir} onAbrirClienteId={()=>setClienteAAbrir(null)} userActual={user}/>}
          {active==="proveedores"&&puedeVer(user.rol,"proveedores")&&<Proveedores data={data} setData={setData} userActual={user}/>}
          {active==="maquinas"&&puedeVer(user.rol,"maquinas")&&<Maquinas data={data} setData={setData} userActual={user} irACliente={irACliente} irAAviso={irAAviso} irAParte={irAParte} abrirMaquinaVista={maquinaVistaAbrir} onAbrirMaquinaVista={()=>setMaquinaVistaAbrir(null)}/>}
          {active==="ventas"&&puedeVer(user.rol,"ventas")&&<Ventas data={data} setData={setData} userActual={user}/>}
          {active==="visitas"&&puedeVer(user.rol,"visitas")&&<DiarioVisitas data={data} setData={setData} userActual={user}/>}
          {active==="tareas"&&puedeVer(user.rol,"tareas")&&<Tareas data={data} setData={setData} userActual={user} abrirTareaId={tareaAAbrir} onAbrirTareaId={()=>setTareaAAbrir(null)}/>}
          {puedeVer(user.rol,"partes")&&<div style={{display:active==="partes"?"block":"none"}}><Partes data={data} setData={setData} userActual={user} abrirParteId={parteAAbrir} onAbrirParteId={()=>setParteAAbrir(null)}/></div>}
          {active==="albaran"&&puedeVer(user.rol,"albaran")&&<Albaran data={data} setData={setData} userActual={user}/>}
          {active==="stock"&&puedeVer(user.rol,"stock")&&<Stock data={data} setData={setData} userActual={user}/>}
          {active==="inventario"&&puedeVer(user.rol,"inventario")&&<Inventario data={data} setData={setData} userActual={user} isMobile={isMobile}/>}
          {active==="documentacion"&&puedeVer(user.rol,"documentacion")&&<Documentacion data={data} setData={setData} userActual={user} filtroInicial={docFiltro} onFiltroConsumido={()=>setDocFiltro(null)}/>}
          {active==="calendario"&&puedeVer(user.rol,"calendario")&&<Calendario data={data} setData={setData} userActual={user} irAAviso={irAAviso} isMobile={isMobile}/>}
          {active==="chat"&&puedeVer(user.rol,"chat")&&<Chat data={data} setData={setData} userActual={user} addNotif={addNotif} isMobile={isMobile}/>}
          {active==="fichaje"&&puedeVer(user.rol,"fichaje")&&<Fichaje data={data} setData={setData} userActual={user}/>}
          {active==="passwords"&&puedeVer(user.rol,"passwords")&&<Passwords data={data} setData={setData} userActual={user} isMobile={isMobile}/>}
          {active==="usuarios"&&puedeVer(user.rol,"usuarios")&&<Usuarios data={data} setData={setData} userActual={user}/>}
          {active==="contabilidad"&&puedeVer(user.rol,"contabilidad")&&<Contabilidad data={data} setData={setData} userActual={user}/>}
          {active==="ajustes"&&puedeVer(user.rol,"ajustes")&&<Ajustes data={data} setData={setData} onPrueba={onPrueba} userActual={user}/>}
        </main>
      </div>
      {isMobile&&<BottomNav/>}
      {isMobile&&<MoreDrawer/>}
      {cuentaOpen&&<MiCuenta userActual={user} setData={setData} onUpdateUser={setUser} onClose={()=>setCuentaOpen(false)}/>}
      {popupQueue.length>0&&(()=>{
        const p=popupQueue[0];
        const pos=totalPopups-popupQueue.length+1;
        return(
        <div style={{position:"fixed",inset:0,background:"rgba(5,8,15,.78)",display:"flex",alignItems:"center",justifyContent:"center",zIndex:3000,padding:20}}>
          <div style={{width:"min(440px,100%)",maxHeight:"85vh",overflowY:"auto",background:"#151b2a",border:"1px solid "+p.color+"55",borderRadius:18,padding:"26px 24px",boxShadow:"0 30px 80px rgba(0,0,0,.6)"}}>
            <div style={{display:"flex",alignItems:"center",gap:12,marginBottom:16}}>
              <div style={{width:42,height:42,borderRadius:11,background:p.color+"20",display:"flex",alignItems:"center",justifyContent:"center",color:p.color,flexShrink:0}}><Icon name="mail" size={20}/></div>
              <div style={{color:p.color,fontWeight:900,fontSize:16,letterSpacing:".5px",textDecoration:"underline"}}>{p.categoria}</div>
            </div>
            {p.linea&&(
              p.cliente ? (
                <div style={{marginBottom:(p.vence||p.lista)?6:18}}>
                  <div style={{color:"#f1f3f9",fontSize:14,fontWeight:700,lineHeight:1.4}}>{fraseMayus(p.linea)}</div>
                  <div style={{color:"#fff",fontSize:14,fontWeight:700,lineHeight:1.4}}>{p.cliente.toUpperCase()}</div>
                  {p.municipio&&<div style={{color:"#dae0ee",fontSize:12,fontWeight:600,lineHeight:1.4}}>{capitalizaNombre(p.municipio)}</div>}
                </div>
              ) : (
                <div style={{color:"#f1f3f9",fontSize:14,fontWeight:700,lineHeight:1.4,marginBottom:(p.vence||p.lista)?6:18}}>
                  {p.categoria==="TAREAS" ? fraseMayus(p.linea) : fmtFrase(p.linea)}
                </div>
              )
            )}
            {p.vence&&<div style={{color:p.vence.startsWith("vencida")?"#ef4444":"#e4e9f6",fontSize:12,fontWeight:700,marginBottom:18}}>{conPunto(p.vence)}</div>}
            {p.lista&&(
              <div style={{marginBottom:18}}>
                {p.lista.map((l,i)=>(
                  <div key={i} style={{display:"flex",gap:8,color:"#c7d0e0",fontSize:13,lineHeight:1.5,marginBottom:i<p.lista.length-1?10:0}}>
                    <span style={{width:6,height:6,minWidth:6,borderRadius:"50%",background:p.color,marginTop:6,flexShrink:0}}/>
                    <div>
                      <div>{fraseMayus(l.texto)}</div>
                      {l.cliente&&<div style={{color:"#f1f3f9",fontWeight:700}}>{l.cliente.toUpperCase()}</div>}
                      {l.municipio&&<div style={{color:"#dae0ee",fontSize:12,fontWeight:600}}>{capitalizaNombre(l.municipio)}</div>}
                      {l.vence&&<div style={{color:l.vence.startsWith("vencida")?"#ef4444":"#dae0ee",fontSize:12,fontWeight:600}}>{conPunto(l.vence)}</div>}
                    </div>
                  </div>
                ))}
              </div>
            )}
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",gap:10}}>
              <span style={{color:"#e4e9f6",fontSize:12,fontWeight:800}}>{pos}/{totalPopups}</span>
              <button onClick={cerrarPopup} style={{...btnPrimary,padding:"10px 22px",fontSize:13,fontWeight:800}}>CERRAR</button>
            </div>
          </div>
        </div>
      );})()}
    </div>
  );
}

export default function App() {
  return <AppErrorBoundary><AppInner/></AppErrorBoundary>;
}
